    ["{{先生|小姐}}！蒙特利大师的《伯爵归来》正在金梧桐剧场热映！"] = "{{Mr.|Ms.}}! Спектакль Мастера Монтерея «Возвращение графа» сейчас идет в театре «Золотой Феникс»!",
    ["{{先生|小姐}}，请一定要小心！道格看上去很痛苦……"] = "{{ Mr.| Ms.}}, пожалуйста, будьте осторожны! Даг выглядит так, будто ему очень больно...",
    ["——{{PlayerName}}——{{PlayerName}}——"] = "——{{PlayerName}}——{{PlayerName}}——",
    ["——{{PlayerName}}——请请请请注意您的身份，您无权干预演出的正常进行。"] = "— {{PlayerName}} — Пожалуйста-пожалуйста-пожалуйста, помните о своём статусе: вы не имеете права вмешиваться в ход представления.",
    ["——哎呀！怎么有只青蛙？！唔，看起来倒没摔坏……"] = "— О боже! Почему там лягушка?! Хм, вроде не сломано...",
    ["“一阵悠扬的琴声响起……”"] = "«Раздается мелодичный звук цитры...»",
    ["“以心为誓，守护吾爱”，看来是杰温先生送给芙拉女士的。她让这件信物陪自己入睡吗……"] = "«Клянусь сердцем защищать мою любовь». Кажется, это был подарок мистера Джевона госпоже Фуле. Позволяет ли она этому сувениру сопровождать ее во сне...",
    ["“但待到白昼睁开了眼睛”"] = "«Но когда дневной свет открыл глаза»",
    ["“做得不错，{{小伙子|小姑娘}}很有前途嘛！“一只海精灵随着夸奖一同出现了，面对被抓的结局表现得很平静，“这是给爱知识人的奖励。"] = "«Молодец, {{ young man | young lady }}, у тебя светлое будущее!» Вместе с похвалой появился Морской Дух, оставаясь спокойным перед лицом того, что его поймали. «Это награда для тех, кто любит знания».",
    ["“吵死了！怎么有人大半夜不睡觉啊！”一只海精灵骂骂咧咧地出现，哼哼唧唧地被抓住了。"] = "«Так шумно! Почему кто-то не спит посреди ночи!» Появился Морской Дух, ругаясь и ворча, и был пойман на его скулении.",
    ["“她便在晕眩中蔫萎凋落”"] = "«Она завяла и упала в головокружительную дымку»",
    ["“她的花一夜开到天明”"] = "«Её цветы цвели всю ночь до самого рассвета»",
    ["“所有人都会死，包括我”……什么意思？"] = "\"Все умрут, в том числе и я\"... Что это значит?",
    ["“正义”女士委托我，安排你在这里见习一段时间，学习处理一些事件。"] = "Леди Джастис поручила мне организовать для вас стажировку здесь на некоторое время, чтобы вы научились справляться с некоторыми инцидентами.",
    ["“母亲”眷顾你！“母亲”照耀你！"] = false,
    ["“母亲”！“母亲”！"] = "\"Мать\"! \"Мать\"!",
    ["“祂将在此处诞生新的子嗣。”"] = "«Здесь он родит новое потомство».",
    ["“窥秘人”……途径……序列6…………卷轴教授……"] = "«Жрец Тайн»... Путь... Последовательность 6... Профессор Свитков...",
    ["“血迹”已经干了，颜色却还很鲜红。如果是血，颜色应该更黯淡。"] = "«Пятно крови» высохло, но цвет по-прежнему ярко-красный. Если бы это была кровь, цвет должен был бы быть более тусклым.",
    ["“被凝视羞得无处可躲”"] = "«Стыдно взгляду, некуда спрятаться»",
    ["“韦尔奇、娜娅、克莱恩，1348年于霍伊大学”。"] = "«Уэлч, Найя, Клейн, 1348 год, Университет Хой».",
    ["……"] = false,
    ["………………"] = false,
    ["……一个彻头彻尾的怪物。请你……帮帮他吧。"] = "...полный монстр. Пожалуйста... помогите ему.",
    ["……不如先向他打听一下。"] = "...Почему бы сперва не расспросить его?",
    ["……不知道她收到请柬了吗？"] = "...Интересно, получила ли она приглашение?",
    ["……什么情况？"] = "...Что происходит?",
    ["……呼，梦中并没有更多的信息。"] = "...Уф, больше никакой информации во сне не было.",
    ["……唤醒他，让他从痛苦中解脱吧。"] = "...Разбуди его и позволь ему освободиться от боли.",
    ["……嗬……报幕……员……"] = "...Ха... Диктор...",
    ["……头好疼……"] = "...У меня так болит голова...",
    ["……好。不要逞强，我去找西迦他们支援。"] = "...Хорошо. Не заставляйте себя; Я пойду искать Сигу и остальных для поддержки.",
    ["……好孩子，安息吧。"] = "...Хороший ребенок, покойся с миром.",
    ["……对了，她会回来吗？"] = "...Кстати, она вернется?",
    ["……我乞求女神的力量……我期待黑夜的眷顾……"] = "...Я молю о силе богини...Я с нетерпением жду милости ночи...",
    ["……最近有人举报莱纳工厂传出了奇怪的声音，难道就是这个？"] = "...Кто-то недавно сообщил о странных звуках, доносящихся с фабрики Лейнер. Может ли это быть оно?",
    ["……朋友，你可能是误会了，我真的没有危害"] = "...Друг, возможно, ты неправильно понял; Я действительно не представляю угрозы.",
    ["……杀害韦尔奇先生和娜娅女士的罪犯已全部落网，相信蔓延在廷根的恐慌气氛将得到缓解……"] = "...Преступники, убившие мистера Уэлча и мисс Найю, схвачены. Смеем надеяться, что охватившая Тинген паника наконец утихнет...",
    ["……殿下……"] = "...Ваше Высочество...",
    ["……殿下，这是一种血肉魔法，通过被吞食的方式让灵体寄生于他人体内，并逐渐控制吞食者的身体，达到灵体永生的目的……"] = "...Ваше высочество, это разновидность магии плоти и крови: будучи съеденным, духовное тело паразитирует внутри чужого организма и постепенно подчиняет тело поглотившего, достигая тем самым бессмертия духа...",
    ["……瑞尔·比伯的位置。"] = "...Местоположение Рэя Бибера.",
    ["……背叛者，渎神的……叛徒！"] = "...Предатель, кощунственный... перебежчик!",
    ["……这应该就是尤朵拉了。"] = "...Это, должно быть, Йодора.",
    ["……这里有好多孩子哭声，令人绝望。"] = "...Здесь так много плачущих детей, что это отчаяние.",
    ["……除了玛丽安之外，其他人都离开。"] = "...Все, кроме Марианны, уходите.",
    ["……黑色的怨念沿着玫瑰的枝干，一路延伸到了地底！"] = "...Черная обида преследовала стебли роз до самого подземелья!",
    ["……！？"] = false,
    ["《不上班如何赚大钱》……咦？！"] = "«Как заработать большие деньги, не работая»… А?!",
    ["《大侦探芒森》整理成册，即将出版……"] = "Книга «Великий детектив Мансон» собрана в сборник и вот-вот будет опубликована...",
    ["《学会看书》？我要是会看进去这本书还要学吗真是的。"] = "«Учимся читать»? Если бы я умел читать, нужно ли бы мне было учиться по этой книге? Серьезно.",
    ["《安提哥努斯家族笔记》在瑞尔·比伯手里，但他却彻底失踪了！"] = "«Семейная тетрадь Антигона» находится в руках Риэля Бибера, но он полностью исчез!",
    ["《安提哥努斯家族笔记》在瑞尔·比伯手里，封印物2-049会带我们找到他"] = "«Записки семьи Антигон» находятся у Риэля Бибера, Запечатанный Артефакт 2-049 приведёт нас к нему",
    ["《班西港历年气象记录分析》？"] = "«Анализ метеорологических наблюдений в гавани Банси за минувшие годы»?",
    ["《第四纪所罗门家族历史研究》？"] = "«Исследование по истории семьи Соломона четвертой эпохи»?",
    ["《花栗鼠与落叶舞》？那个书签？"] = "«Бурундук и танец падающего листа»? Эта закладка?",
    ["《观众的自我修养》……作者苏茜，我看看怎么个事。"] = "«Самосовершенствование Зрителя»... Автор: Сьюзи. Ну-ка посмотрим, что тут у нас.",
    ["《赞美太阳》在这，哇这封面怎么全写着赞美太阳。"] = "«Хвала Солнцу» уже здесь. Ух ты, почему на обложке везде написано «Хвалите Солнце»?",
    ["《迪西海湾》快上映了，你一定又想逃票去看，机灵鬼！"] = "«Дикси Бэй» скоро выйдет, ты, должно быть, захочешь зайти и посмотреть его еще раз, ты, умный маленький дьявол!",
    ["一、二、三、四、五、六、七、八……"] = "Раз, два, три, четыре, пять, шесть, семь, восемь...",
    ["一个也没吃到，我好饿！！"] = "Ни единой штучки не досталось, я так голоден!!",
    ["一个人？不对劲，阿尔伯特向来喜欢热闹。"] = "Один? Это неправильно, Альберту всегда нравилось находиться среди людей.",
    ["一个关于“现在”和“过去”的游戏，猜猜哪边能通向“未来”？"] = "Игра о «настоящем» и «прошлом». Угадайте, какая сторона ведет в «будущее»?",
    ["一个女孩和一个迷失的男孩，刚进去不久……"] = "Девушка и потерявшийся мальчик, они только недавно вошли...",
    ["一个小小的心理暗示——顺从它，获得平静；抗拒它，变得热烈。"] = false,
    ["一个杯子……像酒吧扔掉的废品。"] = "Чашка... как выброшенный продукт из бара.",
    ["一个简易锅？但太久没用，已经坏了。"] = "Простой горшок? Но он слишком давно не использовался, он сломался.",
    ["一个过于热情，一个过于沉静……我都看见了。"] = false,
    ["一些痕迹……难道是皮特购买的非凡材料留下的？"] = "Какие-то следы... неужели их оставил Потусторонний материал, купленный Питом?",
    ["一切都是为了月城……"] = "Всё ради Лунного города...",
    ["一切都是为了月城……出来吧！"] = false,
    ["一切都是为了月城……别想逃！"] = false,
    ["一只倒在湖边的竹编鱼篓，有淡淡的鱼腥味，里面的鱼或许已经游回湖中，恢复自由。"] = "Бамбуковая корзина для рыбы, лежащая на берегу озера, со слабым рыбным запахом; рыба внутри, возможно, уже уплыла обратно в озеро, обретя свободу.",
    ["一只海精灵出现了！它沉浸在书籍的海洋中，似乎没有发现自己已经暴露了这件事。"] = "Появился морской эльф! Погрузившись в океан книг, он, похоже, даже не заметил, что выдал себя.",
    ["一只海精灵怒气冲冲地出现了，难以置信在比拼运气上自己居然输了，然而当它出现的时候，它才是真的输了。"] = "Морской дух появился в ярости, не в силах поверить, что он действительно проиграл в соревновании на удачу. Однако в тот момент, когда он появился, он действительно проиграл.",
    ["一地的纸片，好像是我刚才弄乱的。"] = "Бумаги разбросаны по полу, кажется, я их только что перепутала.",
    ["一块拼接成的破布，不过洗得很干净，像是一顶帽子。"] = "Кусок тряпки сшитый, но отстиранный очень чисто, как шапка.",
    ["一定有非凡因素导致他们疯狂……他们的目标是2-049！保护好马车！"] = "Должно быть, какой-то Чрезвычайный фактор заставил их сойти с ума... их цель — 2-049! Берегите карету!",
    ["一封没来得及寄出的信，收件人是霍伊大学的昆汀·科恩资深副教授。"] = "Письмо, которое так и не было отправлено, адресовано старшему доценту Квентину Коэну из Университета Хой.",
    ["一张交易记录表……精灵花、深潜者的舌头、变形怪的脸皮……这里是一处黑市交易点！"] = "Лист записи транзакции... Эльфийский цветок, Язык Глубоководного, Кожа Безликого... Это торговая точка на черном рынке!",
    ["一打精心保存的来自间海郡的信。"] = "Дюжина бережно сохранённых писем из графства Среднего моря.",
    ["一把左轮……有些昂贵，应该是非法的。"] = "Револьвер... довольно дорогой и должен быть незаконным.",
    ["一本厚实的相册，第一页是这三个年轻人的合照。"] = "Толстый фотоальбом. На первой странице — групповое фото этих троих молодых людей.",
    ["一本笔记，这页没有日期，只有一行字——"] = "Блокнот. На этой странице нет даты, только одна строка текста—",
    ["一朵巨大的红花，颜色和月亮的颜色类似，似乎能感应到有人靠近而闭合起来。"] = "Огромный красный цветок, похожий по цвету на луну, кажется, закрывается, когда чувствует чье-то приближение.",
    ["一枚怀表……指针停在凌晨三点。"] = "Карманные часы... стрелки останавливаются в три часа ночи.",
    ["一枚铜币……战争之前的旧便士。"] = "Медная монета... старый довоенный пенсов.",
    ["一楼似乎有宝箱开启了"] = "Кажется, на первом этаже был открыт сундук с сокровищами.",
    ["一楼没有声音…或许菲利普在二楼的卧室。"] = "На первом этаже тишина... возможно, Филипп у себя в спальне на втором.",
    ["一次循环结束了……<P_Yellow>谜题</>也要出现了？"] = "Один цикл закончился... Скоро ли появится головоломка <P_Yellow> </>?",
    ["一次性买这么多？能不能给后面的人留一点！"] = "Покупаете столько сразу? Разве ты не можешь оставить немного людям позади тебя?",
    ["一次次的“救赎”，到底有什么乐趣可言？"] = "Какая вообще радость в этом бесконечном «спасении»?",
    ["一段新的历史迷雾被点亮了。"] = "Освещён новый кусочек Тумана Истории.",
    ["一片布料，熟悉的花纹，这好像是……值夜者制服的一部分？"] = "Кусок ткани, знакомый узор, кажется... часть униформы Ночного Ястреба?",
    ["一群……虫子"] = "Куча... ошибок",
    ["一群不知天高地厚的家伙，竟敢在我的地盘撒野！"] = "Кучка невежественных парней, посмевших разгуляться на моей территории!",
    ["一群普通的红色蚂蚁，凌乱挤在一起，仔细看看，行进路线的确像一句“滚回去”。"] = "Группа обычных красных муравьев, сбившихся в кучу. Если присмотреться, путь, по которому они идут, действительно похож на слова «Вернитесь назад».",
    ["一群被他守护的羔羊，能带来怎样的乐趣？"] = "Какое веселье может принести охраняемая им группа ягнят?",
    ["一股奇异的香气弥漫在魔药房中，一个身影“嗖”地浮现，陶醉地看着药剂，丝毫没意识到自己被捉住了。"] = "Странный аромат наполнил комнату с зельями, и в поле зрения «пролетела» фигура, опьянённо смотрящая на зелье, совершенно не подозревая, что его поймали.",
    ["一般来说，序列等级越高，可以掌控的非凡能力越强，但……"] = "Как правило, чем выше уровень Последовательности, тем сильнее потусторонние способности, которыми можно овладеть, но…",
    ["一起打回去！"] = "Ударьте его вместе!",
    ["一起来跳舞！"] = "Давайте танцевать вместе!",
    ["一起过去吧。"] = "Давайте пойдем вместе.",
    ["一道送分题，像是儿童游戏……"] = "Совместное начисление очков похоже на детскую игру...",
    ["万物……永不消亡！"] = "Всё сущее... никогда не погибнет!",
    ["万物……生长！"] = "Все вещи... растут!",
    ["万物皆有阴影，堕落隐匿其中！"] = false,
    ["上次调查的结果提交给总部，圣堂的回复是“最深处的污染来自红月之上”。"] = "Результаты прошлого расследования были переданы в штаб; ответ Собора гласил: «Глубочайшая скверна исходит с Алой Луны».",
    ["上车吧，不要让专家等太久。"] = "Садитесь в машину; не заставляйте эксперта ждать слишком долго.",
    ["下次再与你相会吧，美丽的女士。（临时）"] = "Давай встретимся в следующий раз, прекрасная леди. (Временный)",
    ["不——时代的洪流，永不终结！"] = "Нет, поток эпохи никогда не кончается!",
    ["不……不！知识为什么……抛弃我……"] = "Нет... нет! Почему... оставил меня...",
    ["不……我不是这样的……"] = "Нет... я не такой...",
    ["不可亵渎……我的光辉……"] = "Не богохульствуйте... мой блеск...",
    ["不听话的孩子……要挨打的。"] = "Непослушные дети... заслуживают избиения.",
    ["不喜欢尤朵拉的笛声吗？我努力练习了很久的……"] = "Тебе не нравится игра Йодоры на флейте? Я очень усердно тренировался в течение долгого времени...",
    ["不在仓库门口啊……"] = "Не у входа на склад...",
    ["不在这里……"] = "Не здесь...",
    ["不在？不是在这里集合吗……她逃走了？"] = "Не здесь? Разве мы не должны были встретиться здесь... Она сбежала?",
    ["不好，2-049逃脱了，小心它的非凡诅咒！"] = "Нет, 2-049 сбежал, остерегайтесь его необычайного проклятия!",
    ["不好，他好像要失控了，快控制住他！"] = "О нет, похоже, он вот-вот потеряет контроль. Быстро, удержите его!",
    ["不好，她要逃走！"] = "О нет, она пытается сбежать!",
    ["不好，有人被滞涩了，快推醒他！"] = "Нет, кто-то застрял. Толкайте его, чтобы разбудить!",
    ["不好，被拦住了。"] = "О нет, нас заблокировали.",
    ["不好，路被堵死了！大家合力击破它！"] = "О нет, дорога заблокирована! Все, работайте вместе, чтобы преодолеть это!",
    ["不好，这水龙卷也忒强了！快找找可以加入什么破坏汤底！"] = false,
    ["不如用卜杖占卜试一试吧。"] = "Может, стоит попробовать погадать с помощью гадательного жезла?",
    ["不妙啊似乎有奇怪的东西要出来了，门口的石板好像在闪光！"] = "Это плохо, кажется, вот-вот вылезет что-то странное, каменная плита у двери словно сверкает!",
    ["不妙，里面有什么正在散发邪异的气息！"] = "Нехорошо, внутри что-то есть, излучающее злую ауру!",
    ["不对，不对……这才是我的领结！"] = "Нет, нет... это мой галстук-бабочка!",
    ["不对，他已经不能被称为人类了！"] = "Нет, его уже нельзя назвать человеком!",
    ["不小心碰到了一下天平…空间内的秩序似乎不受控制了！"] = "Случайно коснулся весов... Кажется, порядок в пространстве вышел из-под контроля!",
    ["不少人抢着要帮你处理琐事，你只管对付正主就行。 "] = false,
    ["不属于这个时代的愚者……"] = "Шут, не принадлежащий этой эпохе",
    ["不必忧虑，用光明驱散黑暗，这里就能恢复往日的宁静了。"] = "Не тревожьтесь. Разгоните тьму светом, и здешний край вновь обретет былое спокойствие.",
    ["不必担心，《救赎圣典》中的祂只是重现的历史投影，不具备原本的力量，前进吧。"] = "Не волнуйтесь, версия о Нем в «Книге Спасения» — это всего лишь спроецированная история и не обладает Его изначальной силой. Двигайтесь вперед.",
    ["不成真神，终为灰烬！"] = "Если ты не станешь Истинным Богом, ты превратишься в пепел!",
    ["不用客气。"] = "Пожалуйста.",
    ["不用害怕，过来握住我的手。"] = "Не бойся, подойди и возьми меня за руку.",
    ["不用紧张，请坐。"] = "Не нервничай, пожалуйста, сядь.",
    ["不用紧张，这是一种“入学仪式”。让我们通过这种方式，增进彼此的了解。"] = "Не нервничайте, это своего рода «входная церемония». Давайте воспользуемся этим методом, чтобы улучшить наше взаимопонимание.",
    ["不用顾忌我，拿出你的最大实力就好。"] = "Не сдерживайся ради меня, просто покажи мне всю свою силу.",
    ["不知死活的家伙们，竟然追到了这种地方。"] = "Вы, безрассудные дураки, если подумать, что вы действительно погнались за мной в такое место.",
    ["不知道杜伦刚才在办公室里听到那些话是什么想法……问问他吧。"] = "Интересно, что подумал Дюрен, услышав эти слова только что в офисе... Давайте спросим его.",
    ["不知道琳达和艾里克怎么样了，去看看他们吧。"] = "Интересно, как там Линда и Эрик, пойдем проведаем их.",
    ["不知道福戈还在不在原来的地方……四处找找吧。"] = "Не знаю, на том ли месте еще Фуго... Давайте осмотримся.",
    ["不知道让他等了多久……他没生气吧？"] = "Интересно, как долго я заставлял его ждать... он злится?",
    ["不知道这里发生过什么……"] = "Интересно, что здесь произошло...",
    ["不知道这里有没有人知道海精灵的下落，找个人问问吧。"] = "Интересно, знает ли кто-нибудь здесь местонахождение Морского Духа, давайте найдем кого-нибудь спросить.",
    ["不能……这样……结束！"] = "Это не может... закончиться... вот так!",
    ["不要……不要靠近我……"] = "Не... не подходи ко мне...",
    ["不要乱动！嘶，这领结怎么把我的手也缠进去了……"] = "Не двигайтесь! *Шип*, как же в этом галстуке-бабочке запуталась моя рука...",
    ["不要任由情绪坠落，振作一点，想想高兴的事。"] = false,
    ["不要伤害乌鸦，我们是被牵连的！"] = false,
    ["不要着急，得先搞清现在的情况……也得整理一下房间，这里看起来像个命案现场。"] = "Не спешите. Сначала мне нужно разобраться в текущей ситуации... и мне следует прибраться в комнате; это похоже на место преступления.",
    ["不要阻拦我！"] = "Не останавливай меня!",
    ["不过……也到此为止了！"] = "Впрочем... на этом всё и закончится!",
    ["不过他很活泼，不太像个老师——哪有老师一天到晚做些“黄金雨”之类的实验，拿它们哄妻子开心的……"] = "Но он очень живой, не совсем как учитель - как может учитель целыми днями ставить эксперименты типа \"Золотого дождя\" и использовать их, чтобы осчастливить свою жену...",
    ["不过祭品而已……竟敢阻止我！"] = "Это просто жертва... как ты смеешь меня останавливать!",
    ["不过非凡者的道路从来都是危险和疯狂的，走向失控和死亡也是意料中事。"] = "Однако путь Потустороннего всегда был опасным и безумным; скатиться к Потере Контроля и смерти — тоже ожидаемо.",
    ["不过，没有什么有用的信息。"] = "Однако никакой полезной информации нет.",
    ["不远处好像是……"] = "Там неподалеку вроде бы...",
    ["不错嘛——那么现在开始，热身结束咯。"] = "Неплохо — итак, начнём, разминка окончена.",
    ["不错，很有舞蹈天赋嘛！"] = "Неплохо, у тебя настоящий талант к танцам!",
    ["不错，挑战到此结束。"] = "Неплохо, на этом испытания заканчиваются.",
    ["不！不——！这一切……不会结束的……！神明……终将回归于这片大地……！"] = "Нет! Нет-! Всему этому... не будет конца...! Боги... в конце концов вернутся на эту землю...!",
    ["不！不可能！生下你，教派就放弃了我……你是真实存在的！"] = "Нет! Не может быть! Стоило мне родить тебя, и секта от меня отвернулась... Ты настоящая!",
    ["不！不带食物回去，大家都会变成怪物！不！"] = "Нет! Если мы не вернем еду, все превратятся в монстров! Нет!",
    ["不！我的资本！那是合法的！你们这群……野蛮的强盗！！"] = "Нет! Моя столица! Это законно! Вы, кучка... варварских грабителей!!",
    ["不！我的钱！我的钱！！！我的钱！！！！！"] = "Нет! Мои деньги! Мои деньги!!! Мои деньги!!!!!",
    ["不！黛西……她还在等我教她做苹果派……"] = "Нет! Дейзи... она все еще ждет, пока я научу ее готовить яблочный пирог...",
    ["不，不是那个意思……"] = "Нет, я не это имел в виду...",
    ["不，不要！这些东西，我准备了半年！"] = "Нет, не надо! Я готовила эти вещи уже пол года!",
    ["不，只差一点了，只差一点了！"] = "Нет, почти готово, осталось еще немного!",
    ["不，妈妈！你们害死了妈妈！"] = "Нет, мама! Ты убил маму!",
    ["不，我不同意这么做！"] = "Нет, я не согласен на это!",
    ["不，琳达，不是这样的……"] = "Нет, Линда, это не то...",
    ["与无神响应的愿望，一起安眠。"] = "Покойся с миром вместе с молитвами, на которые боги так и не ответили.",
    ["专心战斗，其他的交给他们。"] = false,
    ["世间愿望，归我执掌！"] = "Все желания мира в моей власти!",
    ["东西很少，摆放整齐，没有什么杂物……"] = "Вещей очень мало, все аккуратно разложено, никакого беспорядка...",
    ["丢人，废物，拳台的耻辱！"] = "Позор, мусор, позор боксерскому рингу!",
    ["两拳？竟然两拳就打倒了布雷德？"] = "Два удара? Она действительно нокаутировала Блейда всего за два удара?",
    ["丰饶……溃散……"] = "Изобилие... рушится...",
    ["为什么菲利普会随身带着你亡夫的怀表？"] = "Почему Филип носит с собой карманные часы вашего покойного мужа?",
    ["为什么要逃呢？我要记住你们的样子……"] = "Зачем же бежать? Я запомню ваши лица...",
    ["为你们奢望的奇迹，忏悔吧！"] = "Покайтесь за чудеса, о которых смели мечтать!",
    ["主动要求跟着你的人不少，沿途的杂事他们会处理，你们专心找目标就行。"] = false,
    ["之前从塔罗会那里拿到了2-049的复制品，应该能在这里派上用场。"] = "Ранее я получил копию 2-049 от Клуба Таро, она должна здесь пригодиться.",
    ["之前从塔罗会那里拿到了格罗塞尔游记的复制品，应该能在这里派上用场。"] = "Ранее в Клубе Таро я получил копию «Путешествий Гросселя», здесь она должна пригодиться.",
    ["乌托邦剧院是“愚者”先生留下的封印物，但内部回廊最近发生了异变，希望里面的“演员”还认得自己的剧本。"] = "Утопический театр — это Запечатанный Артефакт, оставленный господином Шутом, но во внутренних коридорах недавно произошли аномальные изменения. Остаётся надеяться, что находящиеся внутри «актёры» всё ещё помнят свои роли.",
    ["乌鸦会一直注视你。"] = false,
    ["乌鸦都来了，可以开始了。"] = false,
    ["乌黯之主，与历史同在。"] = "Повелитель мрака существует с историей.",
    ["乌黯魔狼，序列2“奇迹师”，祂在这里躲藏了几千年，最终被我主驱逐。"] = "Тёмный Демонический Волк, Последовательность 2 «Мастер Чудес», Он прятался здесь тысячи лет, пока наконец не был изгнан моим Господином.",
    ["乔纳尔医生，我送送您。"] = "Доктор Джонар, я вас провожу.",
    ["乖孩子。"] = "Хороший ребенок.",
    ["也许附近还有其它的线索，再找找看吧。"] = "Возможно, поблизости есть и другие зацепки. Давайте поищем ещё.",
    ["书中藏有黄金般的住所，而这本书里，藏有拯救庄园的秘密——"] = "В книгах есть золотые жилища, а в этой книге — секрет спасения поместья…",
    ["书柜上有血液，不是人类的，闻起来有股海腥味。"] = "На книжной полке кровь. Это не человек; пахнет морем.",
    ["事到如今，只能借用3-888的力量了。"] = "На данный момент у меня нет другого выбора, кроме как одолжить силу 3-888.",
    ["事情已经很清晰了：这里是个黑市交易点，有非凡者介入了这起案件。"] = "Все стало предельно ясно: это торговая точка черного рынка, и в этом деле замешаны необыкновенные люди.",
    ["五……四……三……二……一"] = "Пять... четыре... три... два... один",
    ["五颗子弹，还有一枚用过的空弹壳。"] = "Пять пуль и одна с пустым гильзой.",
    ["享受恐惧吧！你们越恐惧——我就越兴奋！哈哈哈！！！"] = "Наслаждайтесь страхом! Чем больше вы напуганы – тем больше я волнуюсь! Ха-ха-ха! ! !",
    ["享受铁与血的洗礼吧！"] = "Наслаждайтесь крещением железом и кровью!",
    ["亲爱的观众们！欢笑吧！哀恸吧！然后，死亡吧！"] = "Дорогая публика! Смех! Плакать! И тогда умри!",
    ["人回来了，我们走吧。"] = "Люди вернулись, поехали.",
    ["人类凭借机械翱翔于天空，是学习与模仿。"] = "Парение людей в небе на машинах – это обучение и подражание.",
    ["什么东西！怎么动不了了？"] = "Что за чертовщина?! Почему я не могу пошевелиться?",
    ["什么声音？地毯好像不对劲！"] = "Что это был за звук? Ковер кажется снятым!",
    ["什么声音？火柴？"] = "Какой звук? Спичка?",
    ["什么奖杯，跟我们有什么关系？"] = "Какой трофей? Какое это имеет отношение к нам?",
    ["什么小偷？我现在可是拳击手，专门打欺负人的小屁孩！"] = "Какой вор? Теперь я боксер и специализируюсь на избиении детей, которые запугивают других!",
    ["什么都看不到……"] = "Ничего не видно...",
    ["今天天气很好，休息一天。"] = "Погода сегодня отличная, выходной.",
    ["从不强求帮忙，但下次希望你们能看见那些真正需要的人。没有金币奖励。"] = "Я никогда не принуждаю к помощи, но надеюсь, что в следующий раз вы сможете увидеть тех, кто действительно в ней нуждается. Никакой награды в виде золотых монет.",
    ["从场中打碎箱子，寻找物资，合成物资。使用物资，帮助穷人吧！"] = "Разбивайте коробки в поле, чтобы найти припасы и синтезировать их. Используйте припасы, чтобы помочь бедным!",
    ["从贝克兰德到迪西海湾的飞空艇航线开通了……"] = "Открылся маршрут дирижаблей из Баклунда в залив Диши...",
    ["他不会要变成怪物了吧……"] = "Он не собирается превращаться в монстра, не так ли...",
    ["他从教会偷走了怨魂晶石，看来是为晋升为“怨魂”做准备。"] = "Он украл у Церкви кристалл призрака — похоже, готовится к продвижению к «Призраку».",
    ["他们太疯狂，我实在追不上他们。"] = "Они слишком сумасшедшие, я действительно не могу за ними угнаться.",
    ["他们是“月亮仆从”成员，一群狂热信徒。"] = "Они являются членами «Лунного Слуги», группы фанатичных верующих.",
    ["他们是猎龙帮，是瑞尔·比伯认识的人！"] = "Это банда охотников на драконов, люди, которых знал Рэй Бибер!",
    ["他们正在进行献祭，我们要阻止这个仪式！"] = false,
    ["他们的力量变强了，笔记应该就在他们身后的仓库里。"] = "Их сила возросла. Дневник должен быть на складе у них за спиной.",
    ["他们看起来睡得很香。"] = "Похоже, они крепко спят.",
    ["他们能不饿肚子已经是非常难得的了。"] = "Для них уже великое счастье не ложиться спать голодными.",
    ["他们这是在干什么？"] = "Что они делают?",
    ["他们速度很快，我们也得再快一点。"] = "Они очень быстрые, нам тоже нужно быть быстрее.",
    ["他们都是普通人，尽量打晕他们吧。"] = "Они все обычные люди, попробуйте их выбить.",
    ["他会拼上一切，守护伟大母亲的子嗣。"] = "Он рискнет всем, чтобы защитить потомство Великой Матери.",
    ["他入梦了，抓紧时间击破护盾！"] = "Он погрузился в сон, скорее пробивайте щит!",
    ["他卜杖寻人的能力，真不错，好用。"] = "Его способность использовать лозоходную удочку для поиска людей действительно очень хороша и очень полезна.",
    ["他因为愤怒已经失去理智了！得赶紧拦住他！"] = "Он потерял рассудок от гнева! Надо остановить его быстро!",
    ["他在与污染对抗，我们需要帮助他！"] = "Он борется с осквернением, нам нужно ему помочь!",
    ["他在阻拦我们……不好！他想把我们击退到尸潮里！"] = "Он блокирует нас... о нет! Он хочет сбросить нас обратно в поток трупов!",
    ["他好像往二楼走了，上楼看看吧。"] = "Он вроде ушел на второй этаж, поднимемся, посмотрим.",
    ["他已经完全失控了……"] = "Он окончательно потерял контроль...",
    ["他怎么变成这样了？这……还是人类吗？"] = "Как он стал таким? Это... все еще человек?",
    ["他急于汲取力量，导致笔记内的力量失控了。尽快控制住局面，防止更多人受到失控力量的污染！"] = "Он стремился поглотить силу, в результате чего сила в нотах вышла из-под контроля. Контролируйте ситуацию как можно скорее, чтобы предотвратить развращение большего числа людей вышедшей из-под контроля силой!",
    ["他曾靠吃怪物勉强求生，但积累的毒素扭曲了他的神志和身体。"] = "Он когда-то с трудом выживал, питаясь монстрами, но накопленные токсины исказили его разум и тело.",
    ["他果然是非凡者……而且那条<P_Yellow>领带</>还是神奇物品。"] = "Он и правда Потусторонний... а тот <P_Yellow>галстук</> ещё и чудесный предмет.",
    ["他现身了！，集中力量消灭他"] = false,
    ["他确实不知道更多了。"] = "Он действительно больше ничего не знает.",
    ["他要是知道了您碰上的麻烦，一定会很心疼的。"] = "Если бы он узнал, в какую беду вы попали, его сердце бы облилось кровью.",
    ["他跑不了多远，我们快些追上去！"] = "Он не сможет далеко убежать, давайте поторопимся и догоним!",
    ["他这几天总是一个人在后院待着，叫他吃饭也不应。"] = "Последние несколько дней он оставался на заднем дворе один. Он даже не отвечает, когда я зову его на ужин.",
    ["令人愉悦的声音，就像卡萝队长的歌声……"] = "Какой приятный звук, совсем как пение капитана Кэрол...",
    ["以为这就结束了吗？"] = false,
    ["以你们的死亡，颂扬家族的荣耀！"] = "Своей смертью вознесите славу нашей семье!",
    ["以先祖的荣耀起誓，冲锋——"] = "Клянувшись славой предков, атакуйте —",
    ["以晨曦之剑，刺破擅闯者的虚伪！"] = "Мечом Зари сокруши лицемерие нарушителей!",
    ["以水银之蛇的名义，标记你的宿命。 "] = "Именем Меркурия-Змеи отметьте свою судьбу.",
    ["仪式完成后，你就能痊愈，就能获得新生了。"] = "После завершения ритуала вы исцелитесь и получите новую жизнь.",
    ["仪式被中断了！我继续追踪主谋，这里就交给你们了。"] = false,
    ["伊妮德，别怕，别怕。"] = "Энид, не бойся, не бойся.",
    ["伊妮德，我们该走了。"] = "Энид, нам пора идти.",
    ["伊森？看来他也被笔记的力量影响到了。"] = "Итан? Кажется, на него тоже повлияла сила нот.",
    ["伊琳不在家吗？"] = "Ирен нет дома?",
    ["优秀的马车夫总能敏锐地找到潜在客户。"] = "Отличный водитель кареты всегда чутко разглядит потенциальных клиентов.",
    ["会长……咦？这里放着本调查报告。"] = "Президент... да? Здесь есть отчет о расследовании.",
    ["伟大又美丽的雕塑……没什么异常。"] = "Величественная и прекрасная скульптура... Ничего необычного.",
    ["伟大母亲……恩赐降临。"] = "Великая Матерь... снисходит благословение.",
    ["伟大母亲，请降下新生的恩典！"] = false,
    ["伦纳德先生，我怎么成了这里的员工？"] = "Мистер Леонард, как я стал здесь сотрудником?",
    ["伦纳德先生？您怎么在这里？"] = "Мистер Леонард? Почему ты здесь?",
    ["伴随着悠扬的曲调，一只海精灵快乐地飘了出来，哼着不知名的小调一头撞进了{{PlayerName}}的怀里。"] = "Под мелодичную мелодию Морской Дух счастливо выплыл наружу, напевая неизвестную мелодию, и врезался прямо в руки {{PlayerName}}.",
    ["似乎……似乎过去好久了……"] = "Кажется... кажется, прошло много времени...",
    ["似乎在这附近了。"] = "Кажется, где-то здесь.",
    ["似乎是小女孩和成年男性的手……这局的结果应该是和棋了，那怎么还在下呢？"] = "Кажется, это руки маленькой девочки и взрослого мужчины... Результатом этой игры должна быть ничья, так почему же в нее до сих пор играют?",
    ["但也要小心，周围的人会因2-049发生滞涩，如果不及时解救，会被同化成木偶"] = "Но будьте осторожны, люди вокруг будут испытывать застой из-за 2-049. Если их не спасти вовремя, они будут ассимилированы марионетками.",
    ["但密修会随时都会再来，笔记的危险也没有消除，封印物2-049的负面效果随时可能影响我们……"] = "Но Школа Мысли Розы придет снова в любой момент, опасность блокнота не устранена, и негативные последствия Запечатанного Артефакта 2-049 могут затронуть нас в любой момент...",
    ["但富人居住区附近怎么会有劫匪？还是在白天？实在是蹊跷……悄悄查看一下吧！"] = "Но как могли оказаться грабители вблизи богатого жилого района? И средь бела дня? Это действительно подозрительно... Давайте спокойно наблюдать!",
    ["但愿女神在天使唱歌的间隙"] = "Пусть Богиня будет там, в промежутках между пением ангелов.",
    ["但我早已窥见了命运，你们的落幕……我必将见证！"] = "Но я уже давно проглядел судьбу; твой занавес... Я буду свидетелем этого!",
    ["但我相信你能处理好。毕竟，你也很特殊。"] = "Но я верю, что ты справишься. В конце концов, ты тоже особенный.",
    ["但是这些门卫看起来可不太友善，先击败他们吧。"] = "Но эти охранники выглядят не очень дружелюбно; давайте сначала победим их.",
    ["但是这里的灵性痕迹混乱，敌人故意留下了混淆的信息，想要阻碍追踪。"] = "Но духовные следы здесь хаотичны; противник намеренно оставил запутанную информацию, чтобы помешать преследованию.",
    ["但那样的结局，会是你们想要的吗……"] = "Но разве такого исхода вы желали?..",
    ["住在郊区的贵族……除此之外，还什么都不清楚。"] = "Дворянин, живущий в пригороде... Кроме этого, больше ничего не известно.",
    ["住手！不许毁掉这里的一切！"] = "Останавливаться! Вам не разрешено разрушать здесь все!",
    ["作为养料，留下你们的灵魂！"] = "Оставьте свои души в качестве пищи!",
    ["作为新员工，你表现很不错。"] = "Для нового сотрудника ты проявил себя отлично.",
    ["作为颜料，还算合格。"] = "Как пигмент вполне сносно.",
    ["你不太舒服？这次我看不见你的想法。"] = "Вы плохо себя чувствуете? На этот раз я не вижу твоих мыслей.",
    ["你为什么要跟着我？不要多管闲事。"] = "Зачем ты идешь за мной? Не суй нос не в свое дело.",
    ["你也会变得和我一样……哈哈（咳嗽）……早晚的事……"] = "Ты тоже станешь таким, как я... ха-ха (кашляет)... это лишь вопрос времени...",
    ["你也想与我共舞一曲吗！"] = "Хочешь тоже потанцевать со мной!",
    ["你也没有资格来告诉我，我应该怎样活下去！"] = "И ты не имеешь права указывать мне, как мне жить!",
    ["你从来就没希望我获得胜利，对吧？"] = "Ты ведь никогда и не желал мне победы, верно?",
    ["你们、你们，请保护好阿诺德……叔叔他在做一些事情、一些很危险的事情。"] = "Ты, ты, пожалуйста, защити Арнольда... Дядя делает некоторые вещи, очень опасные вещи.",
    ["你们以为赢了？账单……永远还不完！"] = "Думаешь, ты выиграл? Счета... бесконечны!",
    ["你们做得已经足够好了。"] = "Вы уже достаточно хорошо справились.",
    ["你们去加入他们吧，学会这套动作也是你们工作的一部分。"] = "Вы идете и присоединяетесь к ним. Изучение этого набора движений также является частью вашей работы.",
    ["你们只能向我许愿，祈求怜悯！"] = "Ты можешь только загадывать мне пожелания и молить о пощаде!",
    ["你们太霸道了！"] = "Вы слишком властны!",
    ["你们将是这份杰作，最后的见证与养料！"] = "Вы станете последними свидетелями и пищей для этого шедевра!",
    ["你们帮了超过二十五个家庭远离了在斩杀线上挣扎的命运。奖励200枚金币。"] = "Вы помогли более чем двадцати пяти семьям избежать гибельной участи. Награда: 200 золотых монет.",
    ["你们帮了超过五个家庭远离了在斩杀线上挣扎的命运。奖励50枚金币。"] = "Вы помогли более чем пяти семьям избежать участи, оказавшейся на линии казни. Награда: 50 золотых монет.",
    ["你们帮了超过十五个家庭远离了在斩杀线上挣扎的命运。奖励100枚金币。"] = "Вы помогли более пятнадцати семьям избежать участи, оказавшейся на линии казни. Награда: 100 золотых монет.",
    ["你们明明就很需要工人，为什么还要辞退我们！"] = "Вам же явно нужны рабочие! Почему вы нас увольняете?!",
    ["你们是谁？！"] = "Кто ты?!",
    ["你们来了，我们走吧……一起回家。"] = "Ты здесь. Пойдем... пойдем домой вместе.",
    ["你们的命运，已被改写。"] = false,
    ["你们看起来非常美味，今晚是用你们来做焗饭呢，还是做浓汤呢？"] = "Вы кажетесь такими аппетитными... Приготовить из вас сегодня запеканку с рисом или сварить густой суп?",
    ["你们这些穷人蝼蚁，真可笑！一辈子在斩杀线上挣扎，一辈子也爬不上来。"] = "Бедные муравьи, как смешно! Всю жизнь боролся на линии казни, но так и не смог подняться наверх.",
    ["你会惹恼“母亲”的！"] = "Вы будете раздражать «Мать»!",
    ["你回来了！太好了！"] = "Ты вернулся! Замечательно!",
    ["你回来了！队长说他们在查尼斯门前等你！"] = "Ты вернулся! Капитан сказал, что они ждут тебя перед Вратами Чаниса!",
    ["你回来了？调查得怎么样？"] = "Ты вернулся? Как прошло расследование?",
    ["你困在封印物里了？"] = "Вы оказались в ловушке Запечатанного Артефакта?",
    ["你在乱讲什么？！"] = "О чем ты говоришь?!",
    ["你在看哪里？镜子才是我。"] = "Куда ты смотришь? Зеркало — это я.",
    ["你就是那个刚加入黑荆棘的新人？"] = "Вы новичок, который только что присоединился к Чёрный Чертополох?",
    ["你已被我……完全洞察！"] = "Я тебя... полностью раскусил!",
    ["你快走吧！被少爷看见了，我们也会有麻烦的。"] = "Тебе следует уйти быстро! Если молодой господин тебя увидит, у нас тоже будут проблемы.",
    ["你怎么了！你还好吗？"] = "Что с тобой не так! Ты в порядке?",
    ["你怎么知道我在找马车？"] = "Откуда ты узнал, что я ищу карету?",
    ["你想实现的理想，可能不仅仅需要时间，也需要更多的同伴。"] = "Идеалы, которые вы хотите реализовать, могут потребовать не только времени, но и большего количества компаньонов.",
    ["你想知道什么是非凡力量，什么是非凡者？"] = "Хочешь узнать, что такое потусторонняя сила и кто такие Потусторонние?",
    ["你所珍视的一切，都有可能被偷走，包括时间。"] = "Все, что вам дорого, может быть украдено, включая время.",
    ["你是历史系毕业生，我们需要研究第四纪文献和遗物的人才。"] = "Вы выпускник исторического факультета; нам нужны таланты для изучения документов и реликвий Четвертой Эпохи.",
    ["你是我煽动的纷争与灾祸中，唯一的意义。"] = "Вы — единственный смысл в раздоре и катастрофе, которые я спровоцировал.",
    ["你是说，学习赚钱的方法？"] = "Вы имеете в виду, научиться методу зарабатывания денег?",
    ["你是谁？为什么跟踪我？"] = "Кто ты? Почему ты следишь за мной?",
    ["你是谁？怎么在我的房间里？"] = "Кто ты? Почему ты в моей комнате?",
    ["你本该……是最鲜艳的那一笔……"] = "Ты должен был быть... самым ярким штрихом...",
    ["你来做安西娅的木偶吧！"] = "Ты станешь марионеткой Антеи!",
    ["你根本不清楚我经历过怎样的痛苦……"] = "Вы даже не представляете, какую боль я испытал...",
    ["你犯规啦！"] = "Вы нарушили правила!",
    ["你的命运，与背叛者们同流。"] = "Ваша судьба связана с предателями.",
    ["你的战斗技巧还要补补课呢。"] = "Ваши боевые навыки все еще нуждаются в некоторых уроках.",
    ["你的时间，到此为止。"] = false,
    ["你的表现非常出色，还亲手击杀了一位邪恶组织的成员。"] = "Ваше выступление было превосходным, и вы лично убили члена злой организации.",
    ["你看他们，饿的、病的、冷的……每一个都需要帮助。但你们帮得过来吗？"] = "Посмотрите на них: голодные, больные, холодные... всем нужна помощь. Но сможете ли вы помочь им всем?",
    ["你知晓世界真相后的表情，就是我玩这场游戏的目的。"] = "Выражение твоего лица, когда ты узнаешь правду об этом мире, — вот ради чего я веду эту игру.",
    ["你确定周围的朋友……还是他们自己吗？"] = "Вы уверены в друзьях вокруг вас... или в себе?",
    ["你给的工作，让他们死在机器旁边。你给的饭，让他们背一辈子的债。"] = "Работа, которую вы им дали, заставляет их умирать рядом с машинами. Еда, которую вы им дали, заставляет их нести долги на всю жизнь.",
    ["你话真多……封印你不也一样拿到报酬？"] = "Ты слишком много говоришь... разве ты не получаешь награду, просто запечатав себя?",
    ["你身体里的力量，对付他们应该没什么问题。"] = "У силы внутри вас не должно возникнуть проблем с ними.",
    ["你轻点啊！啊——我的纽扣！"] = "Будьте нежны! Ах, моя пуговица!",
    ["你这个邪教徒！你残害了多少无辜者的性命，现在你已经无处可逃了！"] = "Ты культист! Скольким невинным жизням вы причинили вред? Теперь вам некуда бежать!",
    ["侠盗出现，还带走了白莉夫人？看来这里刚刚发生了一些事情，还是去打听一下吧。"] = "Появился Призрачный вор и даже забрал леди Берил? Кажется, здесь только что что-то произошло. Я лучше пойду и разузнаю об этом.",
    ["侠盗怎么了？看上去状态有些奇怪……"] = "Что не так с Призрачным вором? Он выглядит немного странно...",
    ["侥幸蒙对。"] = "Совершенно случайно понял.",
    ["保持曲臂伸展！被滞涩的队友动作将会变缓！随时准备推他们一把"] = "Держите руки наготове! Движения скованных союзников замедляются — будьте готовы в любой миг подтолкнуть их!",
    ["保罗惧怕枪声和海。这属于一种战后心理疾病，很多士兵都有，大多数人一生也无法从这恐惧中走出来。"] = "Пол боится стрельбы и моря. Это разновидность послевоенного психологического заболевания; он есть у многих солдат, и большинство людей никогда в жизни не смогут избавиться от этого страха.",
    ["保重。"] = "Заботиться.",
    ["保险起见，先用<P_Yellow>灵视</>确认一下吧！如果他不是非凡者应该可以迅速制服，如果是的话……"] = "На всякий случай давайте сначала воспользуемся духовным зрением <P_Yellow> </> для подтверждения! Если он не Потусторонний, мы сможем быстро его подчинить; если он...",
    ["信徒双手合十，微闭双眼，坚信不疑地祈求，虔诚呼唤祂们的恩赐。"] = "Верующий складывает руки вместе, слегка прикрыв глаза, молится с непоколебимой убежденностью, благочестиво взывая к Их благодати.",
    ["倒计时开始，注意同伴，别让任何人落单。"] = false,
    ["值夜者守这里。这是廷根的中轴线——尸潮要是过这条线，半个城就没了。"] = "Здесь охраняют Ночные Ястребы. Это центральная ось Тингена — если волна зомби пересечет эту линию, половина города исчезнет.",
    ["值夜者，那蜡烛会引来亡灵。我去照看罗德，你解决亡灵。"] = "Ночной Ястреб, эта свеча привлечет нежить. Я пойду присмотрю за Родом, а ты разберись с нежитью.",
    ["做好准备，过会要满足这些情绪要求"] = false,
    ["做得好，你们没有忘记同伴。深呼吸，让我们继续。"] = false,
    ["像所有的光都会被吞噬，前面应该就是尽头。"] = "Как будто весь свет поглотится, это должен быть конец.",
    ["先去下街看看吧。"] = "Давайте сначала пойдём на Лоуэр-стрит.",
    ["先去找苏茜问问看吧。"] = "Пойдем сперва спросим у Сьюзи.",
    ["先四处找找线索吧……"] = "Сначала поищем улики вокруг...",
    ["先埋葬旧的廷根，再新生一座无瑕的新城。"] = "Сначала похороните старый Тинген, а затем постройте безупречный новый город.",
    ["先往前走走吧，说不定能发现什么。"] = "Давайте сначала пройдем вперед, может быть, мы что-нибудь обнаружим.",
    ["先找到菲利普，一切就都清楚了。"] = "Сначала найдите Филиппа, и все станет ясно.",
    ["先找斯林太太问清楚皮特的情况，才更有把握阻止他。"] = "Нам следует сначала попросить миссис Слин прояснить ситуацию с Питом, чтобы у нас было больше шансов его остановить.",
    ["先生，一根火柴，好吗……"] = "Сэр, купите спичку, прошу вас...",
    ["先看看这些案件。"] = "Давайте сначала рассмотрим эти случаи.",
    ["先祖与母亲的亡灵啊……请赐予我力量！"] = "Духи предков и матери... пожалуйста, даруйте мне силу!",
    ["先祖的，印记。"] = "Знак предка, знак.",
    ["先跟我去文献室，了解最基础的知识吧。"] = "Сначала пойдем со мной в архивы, чтобы получить самые базовые знания.",
    ["先随便选杯喝的？红茶或者咖啡？"] = "Хотите сначала выбрать напиток? Черный чай или кофе?",
    ["光明，不会消散……"] = "Свет не погаснет...",
    ["克莱恩，感觉怎么样？"] = "Клейн, как ты себя чувствуешь?",
    ["克莱恩，这里熟悉吗？"] = "Клейн, это место кажется знакомым?",
    ["克莱恩，醒醒！"] = "Клейн, просыпайся!",
    ["克莱恩？哎呀！我的戒指！"] = "Клейн? О боже! Мое кольцо!",
    ["入侵者……撕碎……献给母亲……"] = "Незваный гость... разорвать на части... предложить Матери...",
    ["全都不见了……一次循环结束了？"] = "Всё исчезло... Неужели один цикл завершился?",
    ["全都去死！"] = "Все умрут!",
    ["其他的路都被堵死了，先去大桥上看看吧。"] = "Все остальные пути заблокированы. Сначала пойдём к мосту.",
    ["养活自己都很难，真不知道你是怎么养活我和皮特的。"] = "Мне достаточно сложно поддерживать себя, я правда не знаю, как ты поддержал меня и Пита.",
    ["再仔细看看别人跳的舞是什么舞！"] = "Присмотрись хорошенько к тому, какой танец танцуют остальные!",
    ["再吃不到人，我就要饿疯了，后果很严重"] = "Если я не съем человека в ближайшее время, я умру с голоду. Последствия будут тяжелыми.",
    ["再来几拳！"] = "Нанеси еще несколько ударов!",
    ["再见了！我们下次再会！"] = "До свидания! Увидимся в следующий раз!",
    ["再见了，斯卡纳女士。"] = "До свидания, мисс Скана.",
    ["再试试其他方法吧。"] = "Давайте попробуем другие способы.",
    ["冥界潜藏着恶灵和未知的危险，必须想办法逃出去。"] = "Подземный мир скрывает злых духов и неведомые опасности; Я должен найти способ сбежать.",
    ["冰封！在绝望中，永远别再醒来！"] = "Замороженный! Никогда больше не просыпайтесь в отчаянии!",
    ["准备好的话就再来一次吧。"] = "Если вы готовы, давайте сделаем это еще раз.",
    ["准备好的话，就一同出发吧。"] = "Если вы готовы, давайте отправимся вместе.",
    ["准备好，三、二、一——开始。"] = "Готовьтесь, три, два, один — начинайте.",
    ["准备好，接下来看到的，可能会是个……失控疯狂的怪物。"] = "Будьте готовы; то, что вы увидите дальше, может быть… монстром, потерявшим контроль и сошедшим с ума.",
    ["凝视混沌的阴影，拥抱堕落与死亡！"] = "Взгляните на тени хаоса, примите разложение и смерть!",
    ["几千年的时光，它们依然在守护着什么？"] = "Что они все еще охраняют спустя тысячи лет?",
    ["凡人啊，天使的怜悯已到尽头。"] = "Смертный, милосердию Ангела пришел конец.",
    ["出发吧。"] = "Поехали.",
    ["出口被封印了……这黑雾——是某种非凡力量吗？什么都看不见了！"] = "Выход запечатан... этот черный туман — это какая-то Потусторонняя сила? Я ничего не вижу!",
    ["出来吧，臣服于我的亡魂。"] = false,
    ["击败那些守卫后，地面掉落了一些星光！"] = "После победы над этими стражниками на землю упало немного звездного света!",
    ["分数要靠自己努力！"] = "Оценки зависят от вашего усердия!",
    ["切勿相信所谓的“历史系内部资料”。"] = "Не доверяйте так называемым «материалам отдела внутренней истории».",
    ["刚刚听他们说到那个姓劳维斯的工人，去码头那边找他问问情况吧。"] = "Только что услышал, как они упомянули того рабочего по имени Ловис. Пойдем на пристань и спросим его о ситуации.",
    ["刚才……发生了什么？"] = "Только что... что случилось?",
    ["刚才他们提到“奇怪的事情”？是什么呢……"] = "Они только что упомянули о «странных вещах»? Что это может быть...",
    ["刚才封印物2-049好像发疯了一样……"] = "Только что Запечатанный Артефакт 2-049, казалось, сошёл с ума...",
    ["刚才很危险，记住，保持曲臂伸展，对抗滞涩！"] = "Сейчас это было опасно, помните: держите руки согнутыми и вытянутыми, чтобы не допустить застоя!",
    ["刚才我看到有人在混乱中逃走了，他们逃往的方向是——金秋湖。"] = "Я только что видел, как кто-то сбежал в хаосе; Направление, в котором они бежали, было — озеро Золотой Осени.",
    ["刚才老维德好像朝琳达走过去了，我们也跟过去吧。"] = "Старый Уэйд, кажется, только что шел к Линде, давайте последуем за ними.",
    ["创造一切，掌控一切，怨恨一切。"] = "Всё создавать, всё контролировать, на всё возмущаться.",
    ["别……别靠近……我不想……伤害你……"] = "Не... не подходи ближе... Я не хочу... сделать тебе больно...",
    ["别、别过来！"] = "Не надо, не подходи!",
    ["别以为赢了我就结束了，老大还在后面等着你们！"] = "Не думайте, что все кончено только потому, что вы победили, босс все еще ждет вас позади!",
    ["别伤到老先生！"] = "Не обижайте старого джентльмена!",
    ["别分心！来这边，黑夜会护佑我们！"] = "Не отвлекайтесь! Идите сюда, Вечная Ночь защитит нас!",
    ["别动，让我们好好看看你……"] = "Не двигайся, дай нам хорошенько тебя рассмотреть...",
    ["别怕，跟着烛光往外走。"] = "Не бойтесь, следуйте за светом свечи.",
    ["别急，你之后还有很多时间，来研究和体会它的超凡价值。"] = "Не торопитесь, позже у вас будет достаточно времени, чтобы изучить и оценить его исключительную ценность.",
    ["别担心，有我的“通灵”和你的“入梦”，没有什么能瞒过“通灵者”和“梦魇”。"] = "Не волнуйся, с моим «Спиритизмом» и твоим «Погружением в сон» ничто не скроется от «Медиума» и «Кошмара».",
    ["别敲了，拉着呢！"] = "Хватит стучать, оно занято!",
    ["别碰我——咳咳！"] = "Не прикасайся ко мне — *кхе-кхе*!",
    ["别过来！"] = "Не приходите сюда!",
    ["到了，就是这里。"] = "Мы здесь, это место.",
    ["到管家工作的时间了。"] = "Пришло время дворецкому поработать.",
    ["前一页的日期是1349年6月26日。"] = "Дата на предыдущей странице — 26 июня 1349 года.",
    ["前段时间太忙，一直没去看望阿诺德，据说他和卡萝队长的性格越来越像了，呵呵。"] = "В последнее время я был слишком занят, чтобы навещать Арнольда, говорят, его характер все больше и больше становится похожим на капитана Кэрола, хаха.",
    ["前面似乎有什么不对劲，过去看看吧"] = false,
    ["前面有灵的哀嚎声，当心。"] = "Впереди вой духов, будьте осторожны.",
    ["前面的区域存在危险，等过段时间再来探索吧"] = "Область впереди опасна; подождите некоторое время, прежде чем исследовать его.",
    ["前面还有激光陷阱，看起来就很危险！找准空隙，一口气跳过去。"] = "Впереди лазерные ловушки; они выглядят очень опасными! Найдите пробел и перепрыгните его за один раз.",
    ["前面那个大块头是什么东西……巨型的尸骸？"] = "Что это за громадина впереди... Исполинские останки?",
    ["剑锋所至，跪于王前。"] = "Куда указывает острие меча — склонитесь перед Королем.",
    ["剩下的都带回去……和大家一起吃……"] = "Остальное забери обратно... чтобы поесть со всеми...",
    ["办公室这里没有人影呢……"] = "В офисе никого...",
    ["加入塔罗学派前，似乎还有一项重要的考验在等着我。"] = "Прежде чем вступить в Клуб Таро, меня, кажется, ждет еще важное испытание.",
    ["动不了了……"] = "Не могу пошевелиться...",
    ["区区祭品，也妄想逃走？！"] = "Жалкая жертва еще смеет мечтать о побеге?!",
    ["十、十一、十二……真可惜，不能一起玩了……"] = "Десять, одиннадцать, двенадцать... как жаль, мы больше не сможем играть вместе...",
    ["十枚金币扔进去，赌一个未知。资本的规则，从来都是愿者上钩。"] = "Бросьте десять золотых монет и сделайте ставку на неизвестное. Правила капитала всегда заключались в том, что желающие клюют на наживку.",
    ["协助我！吸取附近的灵力，维持法阵的灵力来源，召唤灵界生物！"] = "Помогите мне! Поглощайте ближайшую духовную энергию, поддерживайте источник духовной энергии магического круга и призывайте духовных существ!",
    ["卑弱的力量……如何与我抗衡！"] = "Слабая сила... как ты можешь соперничать со мной!",
    ["卜者微笑不语，画出了一个连接起点和终点的圆。"] = "Провидец молча улыбнулся и начертил круг, соединяющий начало и конец.",
    ["卜者抽取了一张塔罗牌，于星空之下，推演着命运的方向。"] = "Прорицатель вытянул карту Таро и под звездным небом угадал направление судьбы.",
    ["占位哦"] = false,
    ["占卜显示在廷根市场附近，去看看吧。"] = "Гадание показывает, что он возле рынка Тинген, пойдем посмотрим.",
    ["卡拉，卡拉？艾琳，艾琳……"] = "Кара, Кара? Эйлин, Эйлин...",
    ["卡萝队长牺牲后，小阿诺德被两位虔诚的黑夜信徒收养。"] = "После того, как капитан Карро пожертвовала собой, маленького Арнольда усыновили двое ревностных верующих Богини Вечной Ночи.",
    ["卷轴……需要点燃……即可使用……的力量。"] = "Свиток... нужно зажечь... чтобы использовать его... силу.",
    ["历史的潮流，将以罗塞尔为名！"] = "Волна истории будет названа в честь Розеллы!",
    ["厚实的历史系专著，大部分是漂亮的精装版。"] = "Толстые исторические монографии, большинство из которых представляют собой красивые издания в твердом переплете.",
    ["原来……他只是脱胎于痛苦的，一场幻梦……"] = "Значит... он был лишь призрачным сном, рождённым из боли...",
    ["原来……我也是猎物……"] = "Итак... я тоже жертва...",
    ["原来佩戴这条领带也会影响自我认知，我甚至感觉自己已经变成了侠盗黑皇帝。"] = "Так что ношение этого галстука также влияет на самовосприятие. Я даже чувствую, что стал Призрачным вором, Черным Императором.",
    ["原来大帝设计斯蒂姆宫，是为了登月……"] = "Так вот почему император спроектировал Паровой дворец... чтобы высадиться на Луну...",
    ["原来左右两端的椅子需要形成对称，这样才能恢复一定的秩序。"] = "Оказывается, стулья на левом и правом концах должны быть симметричны, чтобы навести определенный порядок.",
    ["原来是个孩子。安全起见，还是用灵视观察一下吧。"] = "Оказывается, это ребенок. В целях безопасности мне лучше наблюдать за ним духовным зрением.",
    ["原来是这样…将椅子按照一定的规律摆放似乎就能让封印物恢复了!"] = "Так вот оно что... расставив стулья по определенному шаблону, кажется, можно восстановить Запечатанный Артефакт!",
    ["原来，那个“∞”代表无休无止的<P_Yellow>循环</>……"] = "Итак, «∞» представляет собой бесконечный цикл <P_Yellow> </>…",
    ["去卡萝队长的墓前调查一下吧。"] = "Давайте отправимся исследовать могилу капитана Карро.",
    ["去吧，有人在前面等你。"] = "Идите, впереди вас кто-то ждет.",
    ["去外面聊吧。这件事很特殊，尽量不要影响家人。"] = "Давай поговорим снаружи. Этот вопрос очень особенный, постарайтесь не затрагивать семью.",
    ["去对应的地点看看吧。"] = "Давайте проверим соответствующие места.",
    ["去小阿诺德家拜访一下吧，很久没去看望他了。"] = "Пойдем навестить маленького Арнольда; прошло много времени с тех пор, как я его проверял.",
    ["去找<P_Yellow>警官证</>吧，还有给你的惊喜！我们下次再见！"] = "Ступай и отыщи <P_Yellow>полицейский жетон</>, тебя ждет сюрприз! До новой встречи!",
    ["去找伊琳吧。"] = "Иди найди Ирен.",
    ["去正确的地方，释放心中全部的情绪！"] = false,
    ["去问问其他人是什么看法吧。"] = "Давайте спросим других, что они думают.",
    ["又是一个被命运愚弄的可怜虫。我在这里等你好久。"] = "Еще одна бедняга, обманутая судьбой. Я ждал тебя здесь уже давно.",
    ["又是拼图……好像是一束雏菊？"] = "Очередная головоломка... кажется, букет ромашек?",
    ["又是这种感觉……动不了了，可恶！"] = "Опять это чувство... Я не могу пошевелиться, блин!",
