    ["好像有什么东西被点亮了……"] = "Кажется, что-то загорелось...",
    ["好像有呼救声？是从下面传来的。"] = "Кажется, раздался крик о помощи? Оно идет снизу.",
    ["好像没有那种边界了，循环……会就此结束吗？"] = "Кажется, граница исчезла. Цикл... закончится здесь?",
    ["好冷……安西娅不要被……丢下……"] = "Так холодно... Антея не хочет оставаться... оставленной...",
    ["好可怕的灵性波动……那个人到底想做什么？"] = "Какие ужасающие колебания духовности... Что именно пытается сделать этот человек?",
    ["好吧……我给妹妹留张纸条。"] = "Хорошо... Я оставлю записку сестре.",
    ["好嘞，谢谢惠顾！"] = "Хорошо, спасибо за ваше покровительство!",
    ["好困……回去休息吧。"] = "Так спать хочется... Пойдем отдохнем.",
    ["好清香的柠檬味道，甜味与酸味也融合得很好，斯林太太，你的手艺越来越好了！"] = "Такой ароматный лимонный аромат, сладость и кислинка также хорошо сочетаются. Миссис Слин, ваше мастерство становится все лучше и лучше!",
    ["好漂亮的花！"] = "Какие красивые цветы!",
    ["好热闹，斯林太太出新品了？"] = "Это так увлекательно. У миссис Слим новый продукт?",
    ["好疼……我想回家……我想回家……"] = "Больно... Я хочу домой... Я хочу домой...",
    ["好痛……我是谁？我的身体怎么变成了这样？"] = "Мне так больно... Кто я? Как мое тело стало таким?",
    ["好痛苦，快一点、让尤朵拉解脱吧。"] = "Это так больно, поторопись, дай Йодоре свободу.",
    ["好的……我真的很想念他。"] = "Ладно... Я очень скучаю по нему.",
    ["好的。"] = "Хорошо.",
    ["好的，斯维因先生。"] = "Хорошо, мистер Суэйн.",
    ["好的，队长。"] = "Хорошо, капитан.",
    ["好累……感觉灵性被抽空了……天都黑了……"] = "Я так устал... Я чувствую, что моя духовность иссякла... Уже темно...",
    ["好臭！好恶心的粘液，像是什么尸体上留下的……"] = "Это воняет! Такая отвратительная слизь, кажется, что-то осталось на трупе...",
    ["好诡异的声音……是笛声？"] = "Что за жуткий звук... это музыка флейты?",
    ["好饿！我想活下去，和月城一起活下去！"] = "Такой голодный! Я хочу жить, жить дальше с Лунным городом!",
    ["好黑……狩猎时得呆在光里，才不会被怪物袭击。"] = "Здесь так темно... Я должен оставаться на свету во время охоты, чтобы на меня не напали монстры.",
    ["好！琳达的注意力回到了拳台上，比赛马上开始！"] = "Хороший! Внимание Линды снова сосредоточено на боксерском ринге: поединок вот-вот начнется!",
    ["好，不要留下后患。我们现在就赶过去。"] = "Хорошо, нельзя оставлять хвостов. Отправляемся туда прямо сейчас.",
    ["好，克莱恩，帮我个忙，把这些粉末洒在四周。"] = "Хорошо, Клейн, сделай мне одолжение и посыпь этим порошком все вокруг.",
    ["如你所愿。"] = "Как хочешь.",
    ["如果、如果我在历史迷雾中能做些什么的话，是不是能改变你们的结局呢？"] = "Если бы я мог что-то сделать в тумане истории, мог бы я изменить твою концовку?",
    ["如果不想变成木偶，就别被它追到！"] = "Если вы не хотите стать марионеткой, не позволяйте этому поймать вас!",
    ["如果只有你，你还扛得住吗？我看，就算是艾里克向你再打一拳，你都会摔倒在地。"] = "Если бы это был только ты, смог бы ты еще продержаться? Я думаю, что даже если Эрик ударит тебя еще раз, ты упадешь на землю.",
    ["如果我打得过他，我会和你一起去的，只是……我会在这等你好消息！"] = "Если бы я мог победить его, я бы пошел с тобой, но... Я буду ждать здесь твоих хороших новостей!",
    ["如果看见这张照片，小猫说不定能想起来。"] = "Если котенок увидит это фото, возможно, он что-то запомнит.",
    ["如果能联系到弗莱先生，或许就有办法带孩子们回去过生日了。"] = "Если я смогу связаться с мистером Фраем, возможно, есть способ забрать детей обратно на день рождения.",
    ["妈妈……我不怕……只要和你在一起……"] = "Мамочка... я не боюсь... пока я с тобой...",
    ["妈妈……我是谁……"] = "Мама... кто я...",
    ["妈妈的脸是热的，妈妈的手是软的。"] = "Лицо мамы теплое, руки мамины мягкие.",
    ["妈妈！我要妈妈！"] = "Мать! Я хочу маму!",
    ["妈妈，不要抛下安西娅——"] = "Мама, не оставляй Антею...",
    ["妈妈，为什么抛弃安西娅，为什么不爱安西娅——"] = "Мама, почему ты покидаешь Антею, почему ты не любишь Антею...",
    ["妈妈，我是……假的吗……"] = "Мама, неужели я... ненастоящий?..",
    ["妨碍神使大人行动的异端……毁灭！全部毁灭！"] = "Еретики, препятствующие действиям Посланника... Разрушение! Уничтожьте их всех!",
    ["姐姐看起来伤得很重……"] = "Сестра выглядит так, будто ей очень больно...",
    ["姐姐说，多亏了你劝她去学拳击。虽然每天训练很辛苦，但她很开心。"] = "Сестра сказала: спасибо, что ты убедил ее заняться боксом. Хотя тренировки каждый день тяжелые, она очень счастлива.",
    ["姐姐，加油！"] = "Сестра, действуй!",
    ["姐姐，那我先回家了。"] = "Сестра, тогда я сначала пойду домой.",
    ["威瑟尔家族的……荣光……"] = "Слава... семьи Вессель...",
    ["威瑟尔家族的土地，不容冒犯！"] = "Земля семьи Вессель не будет оскорблена!",
    ["子嗣？！"] = "Наследник? !",
    ["孱弱的人类，也可以新生为传奇。"] = "Слабые люди также могут переродиться в легенды.",
    ["它们可能来源于我们的探索，我们的收集，也有可能是我们的敌人……和同伴。"] = "Они могут стать плодами наших поисков, наших находок, а могут остаться от наших врагов... или товарищей.",
    ["它在这里起到什么作用？"] = "Какой цели это здесь служит?",
    ["它最后出现地点就是这里，一家制铅厂。"] = "Последнее известное его местонахождение было здесь, на свинцовом заводе.",
    ["守护……一切……"] = "Берегите... всё...",
    ["守护……不能……停止……继续……战斗！"] = "Охранник... не может... остановиться... продолжать... сражаться!",
    ["守护子嗣，驱逐外人。"] = "Оберегайте потомство, изгоняйте посторонних.",
    ["守桥骑士？看来只能先打败他了。"] = "Рыцарь, охраняющий мост? Похоже, мне сначала придется его победить.",
    ["安全距离？我能轻松窃取，就像这样！"] = "Безопасное расстояние? Я легко могу его украсть, вот так!",
    ["安息吧。你止步的故事，我会替你带走，将它延续下去。"] = "Покойся с миром. Я возьму историю, на которой вы остановились, и продолжу ее дальше.",
    ["安提哥努斯家族的遗物……到底是忠诚，还是背叛？"] = "Реликвии семьи Антигон... это верность или предательство?",
    ["安西娅的“妈妈”，是子爵夫人吗？还是……"] = "«Мать» Антеи — виконтесса? Или...",
    ["完美的演出值得奖励！"] = "Безупречное выступление достойно награды!",
    ["害怕的时候，不妨离同伴近一点。"] = false,
    ["害死自己的血脉……"] = "Погубить собственную плоть и кровь...",
    ["家族的荣耀和血脉，结束了……"] = "Слава и родословная семьи оборвались...",
    ["密修会成员？快阻止他拿走笔记！"] = "Член Школы мысли Роуз? Не позволяйте ему забрать блокнот!",
    ["对不起，作为一名父亲，我没有别的选择。"] = "Мне очень жаль, но у меня как у отца нет другого выбора.",
    ["对不起，姐姐……没能守护好……子嗣……"] = "Прости, сестра... не удалось уберечь... потомство...",
    ["对不起，让你看到了这些，我们没有守护好廷根。"] = "Мне жаль, что я позволил вам это увидеть; мы плохо защищали Тингена.",
    ["对不起，阿诺德，我喜欢你的摇篮曲，但我被这个世界讨厌……我也讨厌这个世界。"] = "Прости, Арнольд, мне нравится твоя Колыбельная, но этот мир меня ненавидит... Я тоже ненавижу этот мир.",
    ["对了，<P_Yellow>{{CustomText}}</>因为风尚度的缘故，有不少值夜者都来帮忙处理沿途的琐事。"] = false,
    ["对了，刚才您提到了化学系……您是大学讲师吗？"] = "Кстати, вы только что упомянули кафедру химии... Вы университетский преподаватель?",
    ["对了，可以尝试一下之前学会的窥密之眼。"] = "Хорошо, я могу попробовать Духовное Видение, которое я изучил ранее.",
    ["对了，桌子上有本笔记，里面可能有记下些什么。"] = "Правильно, на столе лежит блокнот. Там может быть что-то написано.",
    ["对墙前面的这棵树用下生长技能试试，可能会发现什么"] = "Попробуйте использовать навык роста на этом дереве перед стеной; мы могли бы что-то обнаружить.",
    ["对的，对的，好心人救救我吧！"] = "Да-да, добросердечные люди, помогите мне пожалуйста!",
    ["对背叛者，施以湮灭！"] = "Предателям устроить уничтожение!",
    ["封印物2-049会追随安提哥努斯家族后裔的气息，帮助我们找到他。"] = "Запечатанный Артефакт 2-049 будет следовать за аурой Потомка Семьи Антигона, помогая нам найти его.",
    ["封印解开了！快，趁现在逃出去！"] = "Печать снята! Быстрее, воспользуйтесь шансом сбежать!",
    ["小丑还藏在梦境的尽头，继续往上走吧。"] = "Клоун все еще прячется в самом конце сновидения, идем дальше наверх.",
    ["小克莱恩？晚上好。"] = "Маленький Клейн? Добрый вечер.",
    ["小子爵消失了……一切都结束了……"] = "Маленький виконт исчез... все кончено...",
    ["小家伙们，不要害怕，先冷静下来吧。"] = "Малыши, не бойтесь, успокойтесь.",
    ["小家伙，还记得我这个老家伙吗？"] = "Малыш, ты еще помнишь этого старика?",
    ["小心……月亮！"] = "Берегись... луна!",
    ["小心……滞……涩……"] = "Осторожно... вялый...",
    ["小心这片区域，之前探查的同事称呼它为“资本的试炼场”。"] = "Осторожнее в этом районе: коллеги, проводившие разведку раньше, прозвали его «Полигоном капитала».",
    ["小心！又是那些古怪的石像！"] = "Осторожно! Опять эти странные каменные статуи!",
    ["小心，他们已经彻底疯狂！"] = "Осторожно, они совсем сошли с ума!",
    ["小心，他们已经彻底疯狂，保护好2-049！"] = "Будьте осторожны, они совсем сошли с ума, защитите 2-049!",
    ["小心，尸潮来了。"] = "Будьте осторожны, приближается волна трупов.",
    ["小心，慢一点，别被他们发现。"] = "Будьте осторожны, замедляйтесь, не дайте им обнаружить нас.",
    ["小心，躲开！"] = "Берегись, уклоняйся!",
    ["小心，金雨中藏有陷阱。若有人员不慎陷入，附近玩家可使用手中的金币进行赎回。"] = "Осторожно, в золотом дожде скрыты ловушки. Если кто-то угодит в них, ближайшие игроки могут выкупить союзника имеющимися золотыми монетами.",
    ["小戴莉，这些年你们还好吗？廷根还好吗？"] = "Маленький Дэйли, как ты себя чувствовал все эти годы? С Тингеном все в порядке?",
    ["小熊把痛痛吓跑，哥哥不痛……"] = "Медвежонок спугнул боль, брату не больно...",
    ["小男孩身体虚弱，情绪低落。呼，只是个普通的人类小孩子……"] = "Маленький мальчик физически слаб и подавлен. Уф, обычный человеческий ребенок...",
    ["小红帽！把调料都端过来！"] = "Красная Шапочка! Принесите все приправы!",
    ["小艾略特的位置。"] = "Местоположение Маленького Эллиота.",
    ["小黛西……"] = "Малышка Дейзи...",
    ["少废话，把钱给我——"] = "Прекрати ерунду, дай мне денег...",
    ["尤朵拉想和大家一起……回家……"] = "Йодора хочет пойти... домой... со всеми.",
    ["就在<P_Yellow>办公室</>，我带你去见她。"] = "Прямо в офисе <P_Yellow>, </>, я отвезу тебя к ней.",
    ["就是这个味道——是从北边传来的！"] = "Вот этот запах — он идет с севера!",
    ["就是这辆车，快跟上去！"] = "Это карета, поспешите за ней!",
    ["就是这里了<P_Heart>（道路被封锁了，是因为劫案事件？）</>。"] = "Мы пришли <P_Heart>(Дорога перекрыта, это из-за ограбления?)</>.",
    ["就是这里了……"] = "Это место...",
    ["就是这里了。"] = "Это место.",
    ["就是这里了！"] = "Вот оно!",
    ["就是这里了，他给自己选了个最大的舞台。"] = "Это место, он выбрал для себя самую большую сцену.",
    ["尸体说话了！全都死了！我什么都没看见！我不想死！别杀我！"] = "Труп заговорил! Все мертвы! Я ничего не видел! Я не хочу умирать! Не убивай меня!",
    ["尽快把碎片都找回来吧！"] = "Давайте поскорее найдём все осколки!",
    ["居然能找到这里，值夜者，看来比我想象的难缠一点……"] = "Подумать только, ты сможешь найти это место, Ночные Ястребы. Кажется, ты оказался немного более неприятным, чем я предполагал...",
    ["屋里布置得还挺温馨整洁，只是这份剪报有点违和，里面全是关于超自然现象的报道。 "] = "Комната довольно уютная и опрятная, но эта вырезка кажется неуместной; он наполнен сообщениями о сверхъестественных явлениях.",
    ["工人们似乎相信了厂主的话。也可能害怕情况变得更糟，只能妥协。"] = "Рабочие, похоже, поверили словам владельца. Или, возможно, они боятся, что ситуация ухудшится, и у них не будет другого выбора, кроме как пойти на компромисс.",
    ["左右两端的椅子应该存在一些关联…"] = "Между стульями на левом и правом концах должна быть какая-то связь...",
    ["巨人的荣耀，我会背负，千年如此，此后皆然。"] = "Я буду нести славу гигантов, как это было на протяжении тысячи лет и так будет во веки веков.",
    ["巨幅海报的夹缝间贴着一张崭新的小海报。"] = "В разрыв огромного плаката вклеен новенький маленький плакат.",
    ["差点就迷失在回廊里了。愚者的庇护次数有限，不能再大意了。"] = "Едва не заблудился в коридоре. Защита Шута не бесконечна, нельзя больше проявлять беспечность.",
    ["差点忘了，文职人员也有不菲的薪水，尤其对刚毕业的大学生来说。"] = "Чуть не забыл, у гражданского персонала тоже приличная зарплата, особенно для недавнего выпускника колледжа.",
    ["市政广场比平时还热闹，是在举办什么活动吗？"] = "На Муниципальной площади еще оживленнее, чем обычно. Происходит какое-то событие?",
    ["布置一个小仪式，帮你去除……适应风的力量，可能会稍微有点疼……"] = "Устройте небольшой ритуал, который поможет вам избавиться... приспособиться к силе ветра. Это может быть немного больно...",
    ["希望事件能在下午六点前结束……不然就租一辆马车去接班森！"] = "Надеюсь, инцидент закончится до шести часов вечера... иначе мне придется арендовать карету, чтобы забрать Бенсона!",
    ["带回去给队长看看，接下来去占卜俱乐部看看。"] = "Отнесите его капитану, чтобы посмотреть, а затем идите в Клуб гадания, чтобы посмотреть.",
    ["带我去看看廷根现在的样子吧，看看这座我们守护的城市。 "] = "Возьмите меня посмотреть, как сейчас выглядит Тинген, увидеть этот город, который мы охраняем.",
    ["带来安全感的好物件。赞美女神，回归神国的母亲会永远庇佑我。"] = "Хороший объект, который приносит чувство безопасности. Славьте Богиню; мать, вернувшаяся в Царство Божие, всегда защитит меня.",
    ["帮……帮我……"] = "Помогите... помогите мне...",
    ["帮我抵挡住怪物的攻击，我马上启动太阳圣徽破除怪物的伪装"] = false,
    ["幕布拉开，好戏登场！"] = "Занавес поднимается, представление начинается!",
    ["干什么……这是我的……想去警署走一趟？"] = "Что ты делаешь... это мое... хочешь съездить в полицейский участок?",
    ["干得漂亮！"] = "Отличная работа!",
    ["干杯！为了琳达！"] = "Ваше здоровье! К Линде!",
    ["年轻人，请等一下。"] = "Молодой человек, пожалуйста, подождите немного.",
    ["并握在祂温柔的右手里"] = "И держи его в Своей нежной правой руке",
    ["幼兽，该你们出场了"] = "Молодые звери, ваша очередь сиять.",
    ["广、广播体操？"] = "Р-радиогимнастика?!",
    ["庄园苏醒了……必须尽快行动。"] = "Поместье проснулось... надо действовать как можно скорее.",
    ["庄园里种满了苹果树，苹果或许是重要线索，占卜试试吧。"] = "Поместье засажено яблонями. Быть может, яблоки — важная зацепка. Стоит попробовать погадать.",
    ["床底有时也能找到线索，这是你的笔记吗？"] = "Иногда под кроватью можно найти подсказки. Это твой блокнот?",
    ["序列6的欢愉魔女……被母神污染成这样。小心她的镜面和冰晶！"] = "Радостная Ведьма из шестой серии... была вот так осквернена Богиней-Матерью. Берегитесь ее зеркал и кристаллов льда!",
    ["应该不是……地上这是，<P_Yellow>破碎的玫瑰花瓣</>？"] = "Вряд ли... А это что на земле — <P_Yellow>облетевшие лепестки роз</>?",
    ["应该在四个角上洒一些就可以了……"] = "Этого должно быть достаточно, чтобы посыпать немного по четырем углам...",
    ["应该就在里面了，我看看……"] = "Оно должно быть внутри. Дайте-ка подумать...",
    ["应该就在里面，进去吧，接下来要更加小心。"] = "Он должен быть внутри, заходим, впредь будьте осторожнее.",
    ["应该就是这里——这些就是魔药材料吗？"] = "Должно быть, это то самое место — это ингредиенты для зелья?",
    ["应该就是这里，把2-049重新封印。准备进入仓库，大家小心！"] = "Должно быть, это оно. Запечатайте 2-049 обратно. Приготовьтесь войти на склад, будьте осторожны!",
    ["应该没有走太远，在附近找找看。"] = "Им не следовало заходить слишком далеко, давайте осмотримся поблизости.",
    ["店里怎么有这么多人？进去看看。"] = "Почему в магазине так много людей? Давайте зайдем и посмотрим.",
    ["废话太多，匍匐在我的脚下。"] = "Слишком много ерунды, ползи у моих ног.",
    ["廷根市的值夜者们死后大多会葬在一起，就在墓园的中心。"] = "Большинство «Ночных ястребов» в Тингене после смерти хоронят вместе, прямо в центре кладбища.",
    ["廷根，不接受这样的重启……"] = "Тинген не принимает такой перезапуск...",
    ["弗兰奇公寓？这也曾是克莱恩的家？"] = "Доходный дом Франка? Это тоже когда-то было домом Клейна?",
    ["弗莱先生的符咒……是该用上的时候了。"] = "Очарование мистера Фрая... пора им воспользоваться.",
    ["弗莱先生？"] = "Мистер Фрай?",
    ["弗莱队长有事找我们，快去办公室吧。"] = "У капитана Фрая есть для нас кое-что; пойдем в офис.",
    ["弗莱队长突然叫我过来，不知道是发生了什么事……"] = "Капитан Фрай внезапно позвал меня, интересно, что случилось...",
    ["弗莱队长，你找我？"] = "Капитан Фрай, вы меня искали?",
    ["弗莱队长，那个资本家洛克……他到底是什么人？"] = "Капитан Фрай, этот капиталист Рок... кто он на самом деле?",
    ["弱肉强食，这就是世界的法则！"] = "Выживает сильнейший – вот закон мира!",
    ["当会议室里的一切恢复整齐的时候，一只海精灵悄无声息地出现在了椅子旁，试图再次扰乱秩序，被一举擒获。"] = "Когда все в конференц-зале пришло в порядок, рядом со стулом молча появился Морской Дух, пытаясь снова нарушить порядок, но был схвачен одним махом.",
    ["当心！封印物2-049好像感应到什么，进入狂暴状态，负面效果的影响范围变大了！"] = "Осторожно! Запечатанный Артефакт 2-049, кажется, что-то почувствовал и впал в состояние берсерка, дальность его негативных эффектов увеличилась!",
    ["当心，又有非凡怪物冲过来了！"] = "Осторожно, сюда спешат еще больше монстров Потустороннего!",
    ["当然是学习怎样利用非凡能力，并领悟“扮演”的意义！"] = "Конечно же, учиться управлять потусторонними способностями и постигать суть «лицедейства»!",
    ["当然，也顺便接受一些考验。"] = "Конечно, а также попутно принять некоторые испытания.",
    ["当黑暗即将吞噬我，当厄运……咳咳……即将笼罩我，您就是我唯一的曙光……"] = "Когда тьма меня поглотит, когда беда... *кашель*... окутает меня, ты мой единственный рассвет...",
    ["很不幸，你的最后一张牌名叫——“死亡”。"] = "К сожалению, ваша последняя карта называется «Смерть».",
    ["很令人不安啊，队长。"] = "Очень тревожно, капитан.",
    ["很危险吧？如果太危险，逃走也没关系，我、我绝不笑话您。"] = "Это очень опасно? Если это слишком опасно, можно убежать. Я, я точно не буду над тобой смеяться.",
    ["很及时的解救，帮大忙了，谢谢。"] = "Очень своевременное спасение, очень помогло, спасибо.",
    ["很好，你学会自己应对简单的危机了。"] = "Очень хорошо, вы научились самостоятельно справляться с простыми кризисами.",
    ["很好，我已经通知代罚者了。东区和西区由他们负责。"] = "Очень хорошо, я уже уведомил уполномоченных карателей. Они отвечают за Восточный и Западный округа.",
    ["很快就能见到伊琳了吧。"] = "Скоро я смогу увидеть Ирен.",
    ["很抱歉，这匹马跑不动了。"] = "Мне очень жаль, эта лошадь больше не может бежать.",
    ["很有天赋的小朋友，给你点奖励，继续陪我跳一会！"] = "Очень одарённый малыш! Вот тебе награда, потанцуй со мной ещё немного!",
    ["很美妙的气息，不是吗？"] = "Прекрасный аромат, не так ли?",
    ["徒劳的祈愿，是无望者的墓志铭。"] = "Тщетные молитвы — это эпитафии отчаявшегося.",
    ["得小心点，不能被他发现。"] = "Я должен быть осторожен, чтобы не быть обнаруженным им.",
    ["得尽快把它们存放在查尼斯门后，并把情况通报给贝克兰德总部。"] = "Мы должны как можно скорее спрятать их за воротами Чанис и сообщить о ситуации в штаб-квартиру Баклунда.",
    ["得尽快控制住局面，防止更多人受到失控力量的污染。"] = "Ситуацию необходимо взять под контроль как можно скорее, чтобы предотвратить заражение большего числа людей вышедшими из-под контроля силами.",
    ["得想办法先让白莉夫人离开，以免她受到伤害。"] = "Я должен найти способ заставить леди Берил уйти первой, чтобы она не пострадала.",
    ["得想想办法恢复到原来的秩序…"] = "Надо подумать, как вернуть его в первоначальный вид...",
    ["得跟上去看看，他到底要做什么……"] = "Я должен последовать за ним и посмотреть, что он на самом деле собирается делать...",
    ["徘徊在此地的眷属啊，聆听然后遵从。"] = false,
    ["循环……又要开始了吗？"] = "Цикл... он вот-вот начнется снова?",
    ["循环……又要重启了吗？"] = "Цикл... он возобновится снова?",
    ["循着玫瑰怨念留下的痕迹，到处找找看吧。"] = "По следам, оставленным обидой розы, посмотрим вокруг.",
    ["忠实遵从一切规矩，谨守祂的诫命，方能开启灵性之门，获得超然的真谛。"] = "Только верно соблюдая все правила и строго соблюдая Его заповеди, можно открыть дверь духовности и обрести трансцендентную истину.",
    ["快一点，快要跟丢了！"] = "Поторопитесь, мы их потеряем!",
    ["快把2-049引到小丑身边控制他！"] = "Быстро заманите 2-049 к Клоуну, чтобы контролировать его!",
    ["快来看我的新身体，这就是神的力量！"] = "Приходите и посмотрите на мое новое тело; это сила Бога!",
    ["快点跑！安西娅要追上来啦！"] = "Беги быстро! Антея собирается догнать!",
    ["快看！是弗莱队长——他来接应我们了！"] = "Смотреть! Это капитан Фрай — он здесь, чтобы поддержать нас!",
    ["快结束了……"] = "Это почти закончилось...",
    ["快走……快走啊！"] = "Беги... Беги скорее!",
    ["快跟我走，队长在等我们。他说廷根可能要大麻烦了……"] = "Быстро следуйте за мной, нас ждет капитан. Он сказал, что у Тингена могут быть большие проблемы...",
    ["快还给我！"] = "Верни его мне!",
    ["快逃！"] = "Бегать!",
    ["快！在祂向自己再次许愿之前！"] = "Быстрый! Прежде чем Он загадает Себе еще одно желание!",
    ["怀表里有一张照片……这女人好像年轻版的雪莉。"] = "Внутри карманных часов есть фотография... эта женщина похожа на молодую версию Ширли.",
    ["怎么一个人都没有？"] = "Почему здесь никого нет?",
    ["怎么了？"] = "В чем дело?",
    ["怎么会没教过？我虽然上了年纪，但头脑还是很清醒的。"] = "Почему тебя раньше не учили? Хоть я и стар, мой разум все еще очень ясен.",
    ["怎么动不了？"] = "Почему я не могу двигаться?",
    ["怎么可能……怎么可能！你们不该破除牢笼！你们不该逃出来！"] = "Как это возможно... Как это возможно! Тебе не следовало ломать клетку! Ты не должен был бежать!",
    ["怎么有人在争吵？找前面的女士询问一下情况吧。"] = "Почему кто-то спорит? Пойдем, спросим даму впереди о ситуации.",
    ["怎么有这么多人？"] = "Почему здесь так много людей?",
    ["怎么看都是普通的玫瑰花呀，噫？好像在动……让我仔细看看！"] = "Чем она похожа на обычную розу? Ждать? Кажется, он движется... Дайте мне взглянуть поближе!",
    ["怎么都睡着了！混蛋，醒醒！"] = "Да почему вы все уснули?! Придурки, очнитесь!",
    ["怨恨与执念似乎消失了。"] = "Обида и навязчивая идея, кажется, исчезли.",
    ["怪不得菲利普精神崩溃时一直在重复“海水”。"] = "Неудивительно, что Филипп продолжал повторять «морская вода», когда у него случился психический срыв.",
    ["怪我平时太严格？快冲我出出气，这可是最后的机会。"] = "Злишься, что я был чересчур строг? Давай, выпусти пар на мне — это твой последний шанс.",
    ["怪物残留的灵性朝小巷里去了，离他们的头目应该也不远了。"] = "Остаточная духовность монстра направилась в переулок. Лидер не должен быть далеко.",
    ["恭喜你们通过试炼，成功掌控了情绪。"] = false,
    ["恶灵会趋向活物的灵魂，尽量避开它们吧。"] = "Злые духи тянутся к душам живых; старайтесь избегать их.",
    ["恶臭中隐约能闻到一股芬芳馥郁到令人作呕的香气，是红栗花。"] = "В смраде чувствуется слабый ароматный и тошнотворный аромат цветов красного каштана.",
    ["悟性还不错，跟紧卜杖指示的方向。"] = "Ваше понимание неплохое. Внимательно следуйте направлению, указанному лозунгом.",
    ["您不觉得床底存在未知的恐怖吗？正因如此，我才不想轻易打扫。"] = "Вам не кажется, что под кроватью скрывается неведомый ужас? Именно поэтому я не хочу легко его чистить.",
    ["您好……"] = "Привет...",
    ["您是一个真正的天才，也是最温柔的守护者。"] = "Ты настоящий гений и самый нежный хранитель.",
    ["您是这门课的老师？您为什么要卖自己的考题？"] = "Вы преподаватель этого курса? Почему вы продаете собственные экзаменационные вопросы?",
    ["您晚上看这一墙面具，心里不会发毛吗？"] = "Вам не страшно, глядя ночью на эту стену масок?",
    ["您需要一位强大又靠谱、忠诚又谨慎的守护者。"] = "Вам нужен сильный, надежный, верный и осторожный Страж.",
    ["情况紧急，队长你先回总部传递情报，这里交给我们。"] = "Ситуация срочная, капитан, вернитесь в штаб, чтобы передать разведданные, оставьте это нам.",
    ["惊慌吧，逃窜吧，在知识的世界里沉沦吧！"] = "Паникуйте, бегите и погружайтесь в мир знаний!",
    ["惊慌逃窜吧！都是徒劳的挣扎！等待你们的只有被活尸吞没的下场！"] = "Паникуйте и бегите! Это все бесполезная борьба! Единственное, что вас ждет, — это проглотить живые трупы!",
    ["想凭你的小聪明，骗过欺诈之神？"] = false,
    ["想尝试新品？迪西雨露、苏尼亚风情，还是芋圆波波？"] = "Хотите попробовать что-то новое? Дикси Дью, Соня Стайл или Таро Боба?",
    ["想承担命运，还差得远呢。"] = false,
    ["想玩火吗？动次打次——抱歉，你节奏错了！"] = "Хотите поиграть с огнем? Раз, два, три — извините, у вас неправильный ритм!",
    ["愚蠢至极的决策！廷根大学的耻辱！"] = "Глупейшее решение! Позор для Тингенского университета!",
    ["愚钝之人，还妄想点亮黑暗？"] = "Тупой человек, все еще мечтающий осветить тьму?",
    ["感受机械的力量！"] = "Почувствуйте мощь техники!",
    ["感觉好像还不错……"] = "Такое ощущение, что это не плохо...",
    ["感觉好多了，再去中央广场附近看看吧。"] = "Почувствовав себя гораздо лучше, пошли еще раз осматривать центральную площадь.",
    ["感觉如何？"] = "Как вы себя чувствуете?",
    ["感觉湖畔充满了危险，先弄清楚周围情况再说吧。"] = "Я чувствую, что берег озера полон опасности, давайте сначала разберемся с ситуацией здесь.",
    ["感觉精力确实变充沛了……那就赶紧行动吧！"] = "Я чувствую, что моя энергия действительно восполнилась... Тогда давайте действовать быстро!",
    ["感谢你们……你们也是……来自故乡的人吧。"] = "Спасибо вам... Вы ведь тоже... с родины, верно?",
    ["感谢你们帮我找到笔记，祝你们也永远开心！"] = "Спасибо, что помогли мне найти блокнот, я вам тоже желаю счастья навсегда!",
    ["感谢您的馈赠，果然舒服多了。"] = "Спасибо за подарок, так действительно намного удобнее.",
    ["感谢您的馈赠，阿罗德斯。"] = "Благодарю за подарок, Арродес.",
    ["愿他的仁慈和光辉与你我同在，赞美愚者！"] = "Да пребудет Его милость и слава с тобой и со мной, хвала Юродивому!",
    ["愿你们所在之处，永远有雏菊的香气……"] = "Пусть везде, где бы ты ни был, всегда будет аромат ромашки...",
    ["愿女神庇佑，我能活着拿到这个月的双倍薪水。"] = "Да защитит меня Богиня... Хоть бы дожить до двойного жалованья в этом месяце.",
    ["愿您获得永恒的安宁与平静。"] = "Пусть вы обретете вечный мир и спокойствие.",
    ["成为我的镜厅里，又一尊永恒冰雕吧。"] = "Стань еще одной вечной ледяной скульптурой в моем Зеркальном зале.",
    ["成为新生的祭品吧！"] = "Станьте жертвой возрождения!",
    ["成功了……赶紧到处找找线索吧！"] = "Успех... поспешите и ищите подсказки повсюду!",
    ["成功撤离！任务完成！"] = "Успешная эвакуация! Квест завершен!",
    ["成套的因蒂斯风格餐具，在会客餐桌上时刻准备着。"] = "Набор посуды в стиле Интис, всегда готовый на обеденном столе для гостей.",
    ["我……我不能就在这里倒下，啊！太阳——我赞美你！"] = "Я... я не могу упасть здесь, ах! Солнце, я восхваляю тебя!",
    ["我、我是谁……侠盗黑皇帝？不，我是凯娜，我是凯娜……"] = "К-кто я... Благородная разбойница Чёрный Император? Нет, я Кэна, я Кэна...",
    ["我不会让覆灭的悲剧重演！"] = "Я не позволю трагедии разрушения повториться!",
    ["我不做人啦！"] = "Я отвергаю свою человечность!",
    ["我不允许你说姐姐！"] = "Я не позволю тебе говорить о моей сестре!",
    ["我不太擅长找人，如果克莱恩在这里会方便很多。"] = "Я не очень хорошо умею находить людей. Было бы намного проще, если бы Клейн был здесь.",
    ["我不想伤害任何人……我只想生活得更好。"] = "Я не хочу никому причинять вред... Я просто хочу жить лучше.",
    ["我不敢去赌那种可能性。我是说，万一证实真的是我……"] = "Я не смею рисковать такой возможностью. Я имею в виду, что, если подтвердится, что это действительно я...",
    ["我不能去"] = "я не могу пойти",
    ["我为秩序的化身，他们称我为“秩序天平”……对，就是圆桌上的那个。"] = "Я — воплощение порядка, меня называют «Шкала порядка»... Да тот, что на круглом столе.",
    ["我主曾目睹数千年来，一代代人的守护，一次次的抵抗和牺牲。"] = "Мой Господь был свидетелем тысячелетней защиты поколений, неоднократного сопротивления и жертвоприношений.",
    ["我也到后面排队买一个吧！"] = "Я тоже пойду в конец очереди, чтобы купить такой!",
    ["我也在梦里掌控过这股力量。"] = "Я также контролировал эту силу во сне.",
    ["我仔细考察过他们的人品与背景，他们都是很好的人，可以给予阿诺德最好的照顾。"] = "Я тщательно изучил их характер и происхождение. Они оба очень хорошие люди и могут оказать Арнольду лучшую заботу.",
    ["我们会抬头仰望那片夜空"] = "Мы посмотрим на это ночное небо",
    ["我们先找线索，别惊动这里的人。"] = "Сначала поищем улики, не привлекая внимания местных жителей.",
    ["我们到了，还记得这里吗？"] = "Мы здесь. Вы помните это место?",
    ["我们把奖杯叫“菠菜杯”，因为它的纹理和形状像菠菜。丢失前它就放在这里。"] = "Мы называем этот трофей «Кубком шпината», потому что его текстура и форма напоминают шпинат. Его поместили сюда до того, как он пропал.",
    ["我们的安保人员都出任务去了，如果您的事情不紧急的话，可以等他们回来。"] = "Все наши сотрудники службы безопасности уехали на задания. Если ваш вопрос не срочный, вы можете подождать, пока они вернутся.",
    ["我们脱离梦境了？"] = "Мы оставили мечту?",
    ["我们要阻止皮特进入法阵中心，献祭自己召唤邪神。"] = "Мы должны помешать Питу войти в центр магического круга и принести себя в жертву ради призыва злого бога.",
    ["我们还会再回来的！（临时）"] = "Мы вернемся! (Временный)",
    ["我们需要尽快解决隐患，找到管家和知识皇冠。"] = "Нам необходимо как можно скорее устранить скрытую опасность и найти дворецкого и Корону Знаний.",
    ["我们需要战胜她，这是一切的前提，也是你命运的开端。"] = "Нам нужно победить ее; это предпосылка всего и начало твоей судьбы.",
    ["我会不断拆离此处杂乱的灵性碎片。"] = "Я буду постоянно разбирать здесь беспорядочные духовные фрагменты.",
    ["我会听话……我会努力……我会做最好的孩子……"] = "Я буду послушным... Я буду много работать... Я буду самым лучшим ребенком...",
    ["我会尽量克制地，为你展示更强大而神秘的非凡力量！"] = "Я изо всех сил постараюсь сдержаться и показать вам более могущественные и загадочные Необыкновенные силы!",
    ["我会带你去一些熟悉的地方，或许这会让你想起什么。"] = "Я отвезу тебя в знакомые места; возможно, это поможет вам что-то вспомнить.",
    ["我会带给她自由，不惜一切！"] = "Я принесу ей свободу любой ценой!",
    ["我会把你们全部变成分身，然后等着看他醒来后的表情！"] = "Я превращу вас всех в клонов, а потом подожду, чтобы увидеть выражение его лица, когда он проснется!",
    ["我会掌控这个梦境，接下来专心对付小丑吧。"] = "Я буду контролировать этот сон, а дальше давайте сосредоточимся на борьбе с Клоуном.",
    ["我会用它……再度开启循环。"] = "Я воспользуюсь им... чтобы снова запустить цикл.",
    ["我会配合调查的，我要弄清发生了什么。"] = "Я буду сотрудничать со следствием. Я хочу узнать, что произошло.",
    ["我刚才已经看见你被噩梦折磨的心灵。"] = "Я только что видел, как твое сердце терзают кошмары.",
    ["我去吧。"] = "Я пойду.",
    ["我去看看残留的情况。克莱恩，你把这些药剂带给大家。"] = "Я пойду проверю остатки. Клейн, разнеси всем эти зелья.",
    ["我发现了，规则的漏洞，现实的错误。"] = "Я обнаружил лазейки в правилах и ошибки в реальности.",
    ["我变成这样……不能再回月城了，对不起。"] = "Я стал таким... Я больше не могу вернуться в Город Луны, прости.",
    ["我只希望阿尔伯特离危险远一点，在远离我和海洋的地方平安长大。"] = "Я только надеюсь, что Альберт будет держаться подальше от опасности и вырастет в безопасности вдали от меня и океана.",
    ["我只是想欣赏下不对称之美，这能有什么错呢？"] = "Мне просто хотелось оценить красоту асимметрии, что в этом плохого?",
    ["我可怜的黛西，不能再让你受到伤害了。"] = "Бедная моя Дэйзи, я больше не позволю причинить тебе боль.",
    ["我可管不了他了！吉瑞尔，你一会儿见到他，一定要好好说说他。"] = "Я больше не могу его контролировать! Жирель, ты, должно быть, хорошенько с ним поговоришь, когда увидишься с ним позже.",
    ["我听到了……“母亲”在呼唤我！"] = false,
    ["我听到了……丰饶的呼唤！"] = "Я услышал... зов изобилия!",
    ["我听到了什么？亲爱的，请不要伤害它们！"] = "Что я слышу? Дорогой, пожалуйста, не причиняй им вреда!",
    ["我在他身上留了追踪坐标，利用封印物【旅行指南】可以快速传送到附近。"] = "Я оставил ему координаты отслеживания; мы можем использовать мистический предмет [Путеводитель], чтобы быстро телепортироваться поблизости.",
    ["我在神弃之地游荡千年，寄生过很多像你们这样的人。"] = "Я бродил по Заброшенной Земле Богов тысячу лет, паразитируя на многих людях, подобных тебе.",
    ["我大概明白了，第一步……先按照指示调配魔药吧。"] = "Думаю, я понимаю. Первый шаг... приготовим зелье по инструкции.",
    ["我宣告——你的命运，在此终结！"] = "Я заявляю — ваша судьба заканчивается здесь!",
    ["我就是一个小偷，我永远都不可能成为一个真正的拳击手……"] = "Я всего лишь воришка, мне никогда не стать настоящим боксером...",
    ["我就是黑夜中的魅影——侠盗黑皇帝！"] = "Я — фантом в ночи, благородный вор Тёмный Император!",
    ["我已经收集到了很多异象之物，伦纳德先生似乎提起过，我可以去<P_Yellow>俱乐部</>找他换取奖励。"] = "Я собрал множество Объектов Феноменов; Мистер Леонард, кажется, упомянул, что я могу пойти в <P_Yellow>Club</> и обменять их на награды вместе с ним.",
    ["我已经给你们打上印记，你们……逃不掉的……"] = "Я тебя уже отметил, тебе... не уйти...",
    ["我忠实的，仆从。"] = "Мой верный слуга.",
    ["我怀疑他们受到笔记内超凡力量的污染，疯狂后感应到了\"2-049\"的存在，想要阻止我们去找到笔记。"] = "Я подозреваю, что их развратила необычайная сила записок. Сойдя с ума, они почувствовали существование «2-049» и хотели помешать нам найти записи.",
    ["我怀疑他们受到笔记内超凡力量的污染，疯狂后感应到了2-049的存在。"] = "Я подозреваю, что они были испорчены Чрезвычайной силой записной книжки, и, сойдя с ума, они почувствовали существование 2-049.",
    ["我恳求知识降下审判……颤抖吧，愚昧的灵魂！"] = "Я умоляю знание низвести свое суждение... Трепещи, глупая душа!",
    ["我想，我们之后需要好好调查一下这里……不止因为失踪案。"] = "Я думаю, нам нужно позже тщательно исследовать это место... и не только из-за дела о пропаже человека.",
    ["我感受到了力量的加持，波特，剩下的就交给我吧！"] = "Я почувствовал благословение силы, Портер, остальное предоставь мне!",
    ["我找到正常的食物了！快来吃，不会变成我这样的……"] = "Я нашел нормальную еду! Иди поешь, ты не станешь таким, как я...",
    ["我无法再在你的身上看到人性，过去的你至少偶尔会让我感到温暖，但现在的你，才是一个真正的怪物。"] = "Я больше не вижу в тебе никакой человечности. Ты из прошлого хотя бы иногда вызывал у меня чувство тепла, но ты сейчас - настоящий монстр.",
    ["我明明已经……偷走了这个结局……"] = false,
    ["我明白了。"] = "Я понимаю.",
    ["我明白了，我来同幸存者交涉。"] = "Я понимаю. Я пойду и проведу переговоры с выжившим.",
    ["我明白了，晋升可以让我变得更强大……"] = "Я понимаю, продвижение может сделать меня сильнее...",
    ["我曾成为阴谋的祭品，而这次的祭品，是你。"] = "Когда-то я был жертвой заговора, и на этот раз жертвой стал ты.",
    ["我有件事情想要委托。"] = "У меня есть дело, которое я хотел бы поручить.",
    ["我有种奇怪的感觉，像以前也和谁一起做过果子汤。"] = "У меня странное ощущение, как будто я уже готовила с кем-то фруктовый суп.",
    ["我期盼了许久的孩子……"] = "Дитя, о котором я так долго молила...",
    ["我来叫醒他。"] = "Я разбужу его.",
    ["我来和你共舞一曲！\""] = "Я станцую с тобой отрывок!",
    ["我来用仪式法阵召唤灵界生物，用它们对抗敌人！"] = "Я воспользуюсь ритуальным набором, чтобы призвать существ Духовного мира для борьбы с врагом!",
    ["我来让她入梦，不然甩不掉这些眼睛！"] = "Я здесь для того, чтобы дать ей поспать, иначе она не сможет избавиться от этих глаз!",
    ["我来过，我见证，我征服！"] = "Я пришел, я стал свидетелем, я победил!",
    ["我没事了，你也小心些。"] = "Я уже в порядке, но и ты береги себя.",
    ["我申请了封印物“幸运悖论”。在危急关头，愿它能带来足够的幸运。"] = "Я запросил Запечатанный Артефакт «Парадокс Удачи». В кризис, я надеюсь, это принесет достаточно удачи.",
    ["我的专业催缴团队……会确保每一笔都应收尽收。"] = "Моя профессиональная команда сборщиков долгов... проследит, чтобы каждый пенни был стребован сполна.",
    ["我的刀盾"] = "Мой клинок и щит",
    ["我的孩子……别怕，妈妈会一直在你身边……"] = "Дитя мое... не бойся, мама всегда будет рядом с тобой...",
    ["我的孩子即将迎来新生——让我们赞颂“母亲”赐予的一切！"] = "Мой ребенок вот-вот возродится — восхвалим все, что даровано «Матерью»!",
    ["我的小包包，也是个封印物。"] = "Моя маленькая сумка тоже является запечатанным артефактом.",
    ["我的意思是——观众没死光的话，演出就会一直继续！"] = "Я имею в виду — пока публика не вымрет, спектакль будет продолжаться!",
    ["我的愿望是，擅闯者的力量消散！"] = "Я желаю, чтобы сила злоумышленников рассеялась!",
    ["我的梦……好像不只是梦……"] = "Моя мечта... кажется, больше, чем просто мечта...",
    ["我的灵性屏障有些坚持不住了，得尽快解决这些怪物！"] = "Мой духовный барьер больше не продержится; Я должен быстро разобраться с этими монстрами!",
    ["我的灵性还没有完全恢复，接下来的事情就要拜托你了！请一定要说服我的母亲！"] = "Моя духовность еще не полностью восстановилась, так что дальше придется действовать тебе! Пожалуйста, непременно убеди мою мать!",
    ["我的生活又多了一份希望，时刻期盼着乐曲完成的那一天。"] = "В моей жизни появился еще один проблеск надежды, я постоянно с нетерпением жду того дня, когда музыка будет завершена.",
    ["我的胳膊，好痛……"] = "Моя рука... так больно...",
    ["我的舞会，从不邀请活人。但你可以成为镜厅里永不融化的冰雕！"] = "Мой шар никогда не приглашает живых. Но вы можете стать ледяной скульптурой в Зеркальном зале, которая никогда не тает!",
    ["我的观众们！欢笑吧！哀恸吧！在这名为命运的舞台上！"] = "О мои зрители! Смейтесь же! Рыдайте! На этих подмостках по имени Судьба!",
    ["我的领结！！"] = "Моя бабочка!!",
    ["我看到员工手册上写了哀嚎黑市的案件追踪，我可以参与吗？"] = "Я видел отслеживание дел на Стонущем черном рынке в справочнике для сотрудников; могу ли я участвовать?",
    ["我终于……成了真正的尸体……"] = "Я наконец... стал настоящим трупом...",
    ["我给了他们工作，给了饭吃，他们却反过来骂我？"] = "Я дал им работу, дал им еду, а они оборачиваются и проклинают меня?",
    ["我给过你机会了，但是现在，你只能留下自己灵魂的悲鸣……"] = "Я дал тебе шанс, но теперь тебе остается лишь оставить позади вопли собственной души...",
    ["我能看见你心中的疑问，它们像一团乱糟糟的毛线球。"] = "Я вижу вопросы в твоем сердце; они подобны запутанному клубку пряжи.",
    ["我自己的东西，想怎么卖就怎么卖。"] = "Это мои вещи, как хочу, так и продаю.",
    ["我被……滞……涩……"] = "Я... веду себя вяло...",
    ["我要休息了，天还没亮，还来得及打个盹。"] = "Я собираюсь отдохнуть. Еще не рассвело, еще есть время вздремнуть.",
    ["我要找的人会是他们吗？他们跑远了，追上去看看。"] = "Могут ли люди, которых я ищу, быть ими? Они убежали далеко, давайте погоним за ними и посмотрим.",
    ["我要欣赏一个“民族舞”！"] = "Я хочу посмотреть «народный танец»!",
    ["我要欣赏一个“鼓掌舞”！"] = "Я хочу насладиться «Танцем в ладоши»!",
    ["我见工匠，如见理性的辉光。——罗塞尔·古斯塔夫"] = "«Во взгляде на Ремесленника я вижу сияние разума». — Розель Густав",
    ["我见过你……你是怎么进来的？"] = "Я тебя помню... Как ты сюда проник?",
    ["我记得阿诺德的养父母提到过，他好像特别喜欢哪一种面包？"] = "Я помню, как приемные родители Арнольда говорили, что ему особенно нравится определенный вид хлеба?",
    ["我试一试能不能用卜杖寻物法找到他。"] = "Я попробую найти его с помощью биолокации.",
    ["我跟你一起。"] = "Я пойду с тобой.",
    ["我还有别的事，等待你的好消息。"] = "У меня есть другие дела, жду твоих хороших новостей.",
    ["我这就用灵摆占卜验证一下！"] = "Я сейчас же проверю это гаданием на маятнике!",
    ["我这是怎么了……"] = "Что со мной происходит...",
    ["我那个偏执狂兄弟，到底在你们无谓的“牺牲”中，看到了什么可取之处？"] = "Мой брат-параноик, что именно он увидел в твоих бессмысленных «жертвах» стоящего?",
    ["我问问附近的小家伙们……"] = "Позвольте мне спросить малышей поблизости...",
    ["我需要一些时间打断它，掩护我！"] = false,
    ["我需要把受伤的同伴送回圣堂，追捕的任务只能麻烦你们了。"] = "Мне нужно отправить моего раненого товарища обратно в собор; Мне придется побеспокоить вас миссией по преследованию.",
    ["我，我不能辜负大家……"] = "Я, я не могу всех подвести...",
    ["我，我承诺，给你双……不，三倍的报酬！"] = "Я, обещаю, двойную... нет, тройную награду для тебя!",
    ["我，是时代的主角。我，是不朽的传奇！"] = "Я герой времени. Я бессмертная легенда!",
    ["我，是皇帝，亦是……绯红的信徒！"] = "Я — император и в то же время... последователь Алого!",
    ["或许……他还没有布置那场诡异的仪式？"] = "Возможно... он еще не установил этот странный ритуал?",
    ["或许在知识皇冠出现前，这里就已经遭遇了未知的灾难。"] = "Возможно, до появления Короны Знаний это место уже пережило неизвестную катастрофу.",
    ["或许蒸汽与机械系的同学能修好？"] = "Может, студенты с кафедры Пара и Машин смогут это починить?",
    ["或许远没有结束。小心，笔记我来处理。"] = "Возможно, это далеко не конец. Будьте осторожны, я займусь блокнотом.",
    ["或许，你们还需要更多的理解和默契。"] = false,
    ["战争的艺术，在精准打击！ "] = "Искусство войны заключается в точечных ударах!",
    ["战争，永不终结！"] = "Война никогда не кончается!",
    ["战斗……就像神使大人教的那样……战斗！永无休止！"] = "Сражайтесь... так, как учил Посланник... Сражайтесь! Бесконечный!",
    ["战斗平息，看不到热闹的海精灵失落地出现了，直到目目相对，它成为热闹的主角时，才惊觉自己忘记隐身了。"] = "Когда битва утихла, морской эльф, так и не успев поглазеть на веселье, разочарованно показался наружу. Лишь когда их взгляды встретились и он сам оказался в центре внимания, он с ужасом понял, что напрочь забыл остаться невидимым.",
    ["戴上倒是感觉没什么特别的。"] = "При ношении не возникает ощущения чего-то особенного.",
    ["戴莉·西蒙妮女士……"] = "Мисс Дейли Симона...",
    ["戴里克导师平常都待在屏障碎片附近，那里找找看吧！"] = "Наставник Деррик обычно остается возле фрагментов барьера. Давайте посмотрим туда!",
    ["房租、伙食、出行……每一笔账单，都会贴在门口。付不起的人，就会被请出去。"] = "Аренда, еда, проезд... каждый счет будет вывешен на двери. Тех, кто не сможет заплатить, пригласят на свидание.",
    ["房租、药费、马车费……一起找上门的时候，你根本不知道先还哪一笔！"] = "Аренда, лекарства, проезд в омнибусе... когда всё это наваливается разом, понятия не имеешь, за что платить в первую очередь!",
    ["房间内明亮了很多……"] = "В комнате стало намного светлее...",
    ["房间里面有一股非凡气息，但没有看到什么灵异物品。"] = "В комнате присутствует аура Потустороннего, но никаких мистических предметов я не вижу.",
    ["所有人都在等待，只有你在主动出击。恭喜你——卷赢了这场金雨！"] = "Все ждут, только ты проявляешь инициативу. Поздравляем — вы выиграли этот золотой дождь!",
    ["所有灾难的源头"] = "Источник всех бедствий",
    ["所有都将毁灭，一切……同归红月！"] = "Все будет разрушено, все... вместе отправимся на красную луну!",
    ["扉页有名字……霍伊大学历史系，克莱恩·莫雷蒂。"] = "На титульном листе имя... Клейн Моретти, исторический факультет Хойского университета.",
    ["手册上介绍了很多新员工可以做的事……"] = "В руководстве рассказывается о многом, что могут делать новые сотрудники...",
    ["手脚放干净些！竟敢碰公司开出的账单？"] = "Держите руки в чистоте! Как вы смеете трогать векселя, выпущенные компанией?",
    ["手臂还是温热、柔软的……"] = "Рука еще теплая и мягкая...",
    ["打开账单吧。 上面记录了每个工人的欠账清单。洛克用这些账单，把他们绑在这里。"] = "Откройте счет. Он записывает список долгов каждого работника. Рок использует эти законопроекты, чтобы связать их здесь.",
    ["打开账单吧。上面记录了每个工人的欠账清单。洛克用这些账单，把他们绑在这里。"] = "Откройте счет. Он записывает список долгов каждого работника. Рок использует эти законопроекты, чтобы связать их здесь.",
    ["打起精神。这里很危险。"] = "Радость. Здесь опасно.",
    ["执掌混沌的魔女"] = "Ведьма, управляющая хаосом",
    ["扮演？又是扮演……"] = "Действуя? Опять играю...",
    ["找到《海面八英里》了！看着书就闻到了鱼腥味是我的错觉吗。"] = "Нашел «Восьми милях от моря»! Мне кажется, я чувствую запах рыбы, просто взглянув на книгу?",
    ["找到了，必须尽快控制住她。"] = "Нашел. Нужно как можно скорее взять ее под контроль.",
    ["找到了，是这个。"] = "Нашел, это он.",
    ["找到了，这些家伙竟然躲进了遗迹里。"] = "Нашел их. Эти парни на самом деле спрятались внутри руин.",
    ["找到我的弱点了吗？"] = "Ты уже нашел мою слабость?",
    ["找找看……哪一面镜子里，藏着你的恐惧？"] = "Поищи... в каком из зеркал прячется твой страх?",
    ["承受吧！镜中主宰的审判！"] = false,
    ["把它和甜蜜的静默一起摘取"] = "Вырвите это вместе со сладкой тишиной",
    ["抓到你了，下水道的老鼠，这次你别想挣脱！"] = "Поймал тебя, канализационная крыса; на этот раз ты не вырвешься на свободу!",
    ["抱歉……<P_Heart>（好难过，即使只记得一些残缺的片段……我们是很好的朋友，他们都是很好的人……）</>"] = "Извините... <P_Heart>(Это так грустно, хотя я помню только отдельные фрагменты... мы были хорошими друзьями, они все были очень хорошими людьми...)</>",
    ["抱歉，只有切断污染，你们才能获得宁静。"] = "Извините, только прекратив Искажение, вы сможете обрести покой.",
    ["抱歉，我的重感冒还没有完全好——咳，再见，我去下一场宣讲了。"] = "Прошу прощения, я еще не совсем оправился от тяжелой простуды... Кхм! До свидания, мне пора на следующую лекцию.",
    ["抽取你的命运之牌吧——真不错！一张厄运！"] = "Вытяните карту своей судьбы – очень здорово! Карта несчастья!",
    ["拜托你、别生气，我可以去学些新曲子，你喜欢听什么呢？"] = "Пожалуйста, не сердитесь. Я могу выучить несколько новых песен. Что бы вы хотели услышать?",
    ["拜托稍微拿远一点……不是我的，我猜，这是前任租客的遗留物。"] = "Пожалуйста, отнесите его подальше... это не мое. Я думаю, это что-то, оставленное предыдущим арендатором.",
    ["拨弄知识的指针。"] = false,
    ["拳套？给她送过去吧。"] = "Боксерские перчатки? Давайте отнесем их к ней.",
    ["拳赛？听起来还挺有意思的，进去看看吧。"] = "Кулачные бои? Звучит занятно, зайдем поглядим.",
    ["拼图游戏？档案里有记载，只是图案不同。"] = "Головоломка? В файлах это записано, только по другому шаблону.",
    ["拿起这盏灯，它会给予你正确的指引。"] = false,
    ["按照它们出现的顺序，依次整理一下吧。"] = "Давайте расположим их в том порядке, в котором они появились.",
    ["换个思路，骑士的服饰一定是特别提供的，不如从骑士服入手吧。"] = "Давайте изменим наше мышление. Рыцарский наряд должен быть специально предусмотрен. Почему бы не начать с рыцарского мундира?",
    ["掌声和欢呼，为这出荒诞戏画上休止符！"] = "Аплодисменты и возгласы ставят точку в этой абсурдной пьесе!",
    ["掌控情绪需要一些练习，要再试一次吗？"] = false,
    ["掌权者坐于高台，手执权杖，哪怕太阳的起落也要听其号令。"] = "Правитель сидит на высокой платформе, держит скипетр и повелевает даже восходом и заходом солнца.",
    ["接下来只需要用侠盗黑皇帝的身份，劝白莉夫人留下生活就好了。"] = "Далее мне просто нужно использовать личность Призрачного Вора Черного Императора, чтобы убедить леди Берил остаться и жить.",
    ["接下来将是一场苦战，我准备了一批封印物。你们挑选合适的使用。"] = "Следующая часть будет ожесточенной битвой; Я подготовил партию запечатанных артефактов. Выбирайте те, которые вам подходят.",
    ["接下来，从失踪儿童的家庭开始调查吗？"] = "Начнем расследование с семей пропавших детей?",
    ["接住这个，封印物3-0782【变异的太阳圣徽】，能净化亡灵和死尸！"] = "Лови это, Запечатанный Артефакт 3-0782 [Святая Эмблема Мутировавшего Солнца], он может очищать нежить и трупы!",
    ["接受光明的净化！"] = "Примите очищение Светом!",
    ["接受这伟大的重启吧！"] = "Примите эту великую перезагрузку!",
    ["掩埋在黑暗中的愿望，听从我的指引。"] = "Желания, погребенные во тьме, следуйте моим указаниям.",
    ["撕碎新生的祭品，换取你们的自由吧！"] = "Разорвите новорожденную жертву и обменяйте ее на свою свободу!",
    ["擅闯王庭者，无路可逃！"] = "Тем, кто вторгается в Королевский двор, некуда бежать!",
    ["擅闯王庭者，死！"] = "Те, кто вторгнется в королевский двор, умрут!",
    ["擅闯者……死！"] = "Нарушитель... умри!",
    ["收好金币，离开广场。嫌疑资本家洛克上次出现在附近的村镇，我们去查看一下。"] = "Сохраните золотые монеты и покиньте площадь. Подозреваемого капиталиста Рока в последний раз видели в близлежащих деревнях; пойдем проверим.",
    ["收集的信息不足以拼凑出目标的线索……"] = "Собранной информации недостаточно, чтобы собрать воедино подсказки о цели...",
    ["放任他继续下去的话，整个剧院里的人都会陷入危险。"] = "Если ему позволят продолжить, все в театре окажутся в опасности.",
    ["放我走，否则我就把这个小家伙困死在冥界！"] = "Отпустите меня, или я поймаю этого маленького парня в Подземном мире!",
    ["救、救命啊！"] = "По-помогите!",
    ["救命，救命……"] = "Помогите, помогите...",
    ["救救……我……"] = "Спаси... меня...",
    ["救救我！救救我！"] = "Помоги мне! Помоги мне!",
    ["教会遗失了一件重要物品，据线索它可能流入了黑市。"] = "Церковь потеряла важную вещь, и, судя по подсказкам, она могла попасть на черный рынок.",
    ["数千年前，天使和众神们聚集在此。祂们的力量，依然残留在壁画之上。"] = "Тысячи лет назад здесь собрались ангелы и боги. Их сила все еще сохраняется на фресках.",
    ["数量太多了……希望我的灵性撑得住。"] = "Их слишком много... Надеюсь, моя духовность выдержит.",
    ["斯宾纳奇，你绝对没教过我那一招。"] = "Шпинат, ты определенно никогда не учил меня этому движению.",
    ["斯宾那奇，你就是太保守了。"] = "Шпинат, ты слишком консервативен.",
    ["斯林太太说索菲娅今天戴着<P_Yellow>紫色</>的帽子，找找看吧！"] = "Госпожа Слин сказала, что сегодня на Софии <P_Yellow>фиолетовая</> шляпка. Поищи ее!",
    ["无力达成的奢望，该结束了！"] = "Сумасшедшим надеждам, которые невозможно осуществить, следует положить конец!",
    ["无尽的低语，召唤徘徊的阴影！"] = "Бесконечный шепот, призовите блуждающие тени!",
    ["无尽的知识，源自浩瀚星空——"] = "Бесконечные знания, источаемые бескрайним звездным небом...",
    ["无用的挣扎，同我一样，成为尸体吧！"] = "Бесполезная борьба. Так же, как и я, стань трупом!",
    ["无知之人，竟敢打扰萨斯利尔大人的沉睡！"] = "Невежественный смертный, как ты смеешь тревожить сон Господа Сасрира!",
    ["无知的凡人，成为知识与真理的祭品吧！"] = "Невежественные смертные, станьте жертвой знания и истины!",
    ["无知者……在知识的注视下，你将无处遁藏！"] = "Невежда... под взглядом знания тебе некуда будет спрятаться!",
    ["无论祂守候多久，祂的王，和巨人统治下的荣光都回不来了。"] = "Независимо от того, как долго Он будет ждать, Его Царь и слава под властью гигантов никогда не вернутся.",
    ["无论这里发生过什么，只有前进才能找到答案。"] = "Что бы здесь ни произошло, только двигаясь вперед, мы сможем найти ответ.",
    ["无路可退了！大家躲在障碍物后面，避开冲击！"] = "Нет пути назад! Все прячутся за препятствиями и избегают удара!",
    ["既然来了，就都留下来吧！"] = "Раз уж вы пришли, так оставайтесь же здесь!",
    ["日安，准备好了吗，这是一场有关情绪的试炼。"] = false,
    ["日程表像个学校，这合理吗？"] = "Расписание как в школе? Разумно ли это?",
    ["时代的洪流……注定写满我的功绩！"] = "Поток времени... суждено наполниться моими достижениями!",
    ["时空的裂隙，谁也别想逃走！"] = false,
