    ["时间，是最伟大的牢笼。"] = false,
    ["明明空无一人，却总有一种被人盯着的感觉……"] = "Хотя здесь никого нет, у меня всегда такое ощущение, что за мной наблюдают...",
    ["明白，交给我吧！"] = "Понял, оставь это мне!",
    ["昔日“王庭追猎者”的首领，誓死守卫王庭！"] = "Бывший лидер «Охотника Королевского двора», поклявшийся охранять Королевский двор!",
    ["昨天琳达在这里上用一击绝杀击倒了布雷德，今天面对贝尔，她又将有什么样的表现？"] = "Вчера Линда нокаутировала Блейда одним добивающим ударом; сегодня перед Беллом, какое выступление она покажет?",
    ["是<P_Yellow>那个人</>为了让白莉夫人相信自己就是书中的“侠盗黑皇帝”。这是一个骗局！"] = "Для <P_Yellow> этот человек </> должен заставить леди Берил поверить, что он «Призрачный вор, Черный император» из книги. Это мошенничество!",
    ["是{{PlayerName}}{{哥哥|姐姐}}！我姐姐去训练了，她给你留了一封信。"] = "Это {{PlayerName}}{{Brother|Sister}}! Моя сестра пошла на тренировку и оставила тебе письмо.",
    ["是{{PlayerName}}……？怎么这时候过来了？"] = "Это {{PlayerName}}?.. Что привело тебя сюда в такой час?",
    ["是“愚者”先生救了我？还是要小心一点。"] = "Неужели мистер Шут спас меня? Всё же нужно быть осторожнее.",
    ["是一块怀表！"] = "Это карманные часы!",
    ["是位不认识的女士……？"] = "Леди, которую я не узнаю...?",
    ["是你们啊……想要夺走家人……坏蛋……"] = "Это ты... хочешь забрать мою семью... плохих людей...",
