    ["是刚才那个人留下的？他一个人在会议室里做什么？"] = "Было ли это оставлено этим человеком только что? Что он делал один в конференц-зале?",
    ["是圣堂派你们来支援的吗？当心，变异的怪物又来了！"] = "Собор послал вас поддержать нас? Осторожно, мутировавшие монстры снова приходят!",
    ["是安眠药……看来芙拉女士真的很难熬……"] = "Это снотворное... Кажется, госпоже Фуле действительно приходится нелегко...",
    ["是我小时候和父母的合照。"] = "Это фотография меня и моих родителей, когда я был ребенком.",
    ["是时候去廷根的拉斐尔墓园了，波特应该已经到了。"] = "Пришло время отправиться на кладбище Рафаэля в Тингене. Поттер должен был уже приехать.",
    ["是机关怪物——这也算一种机关谜题？！"] = "Это механический монстр... Неужели это тоже считается механизмом-головоломкой?!",
    ["是机关怪物！这也算一种机关谜题？！"] = "Это механический монстр! Это тоже считается загадкой механизма?!",
    ["是来不及了，如果我是一个真正的非凡者就好了。"] = "Слишком поздно, если бы я был настоящим Потусторонним.",
    ["是档案里记载的谜题……需要转动圆环拼好图案。"] = "Это головоломка, записанная в файле... вам нужно повернуть кольцо, чтобы собрать узор.",
    ["是的。你是……"] = "Да. Ты...",
    ["是的，我们得先离开这里，墓园里有太多嘈杂的灵。"] = "Да, сначала нам нужно уйти отсюда. На кладбище слишком много шумных духов.",
    ["是的，谢谢你，好心的{{先生|女士}}。"] = "Да, спасибо вам, {{добрый господин|добрая госпожа}}.",
    ["是知识皇冠带来的星光之力！拾取星光点亮九支蜡烛，或许是击败星象仪者的关键！"] = "Это Сила Звездного Света из Короны Знаний! Подбор звездного света, чтобы зажечь девять свечей, может стать ключом к победе над Пользователем Астролябии!",
    ["是神奇物品！"] = "Это мистический предмет!",
    ["是空的……刚才不是被烧了吗……"] = "Он пуст... разве он сейчас не сгорел...",
    ["是记忆里的其他人？"] = "Это кто-то другой в памяти?",
    ["是谁伤了我同伴！我要你们不得好死！"] = "Кто обидел моего товарища! Я заставлю тебя умереть ужасной смертью!",
    ["是谁擅闯桥头？有我在，你们一个都过不去！"] = "Кто посмел вторгнуться на мост? Пока я здесь, ни один из вас не пройдет!",
    ["是这几页吗？"] = "Это страницы?",
    ["是这次的谜题——我记得，要把4盆雏菊都转到“太阳”下面……"] = "Это задачка на этот раз — помню, мне нужно повернуть все 4 горшка с ромашками под «солнце»…",
    ["是那个熟悉的声音……是“愚者”先生？"] = "Это знакомый голос... это мистер \"Шут\"?",
