    ["是！公主殿下！"] = "Да! Ваше Высочество!",
    ["是，一开始我只是想要找救我妻子的方法，失败之后，却发现非凡将我引向了难以脱身的漩涡。"] = "Да. Сначала я просто хотел найти способ спасти жену. После неудачи я обнаружил, что мир Потустороннего завел меня в водоворот, из которого я не мог выбраться.",
    ["显现吧！传递新生的纽带！"] = "Появляться! Связь, которая несет новую жизнь!",
    ["晚饭时间到了，没时间和你们闹了，受死吧！"] = "Пришло время ужина, не время с вами возиться, готовьтесь умереть!",
    ["普普通通的公园，没有什么特殊。"] = "Обычный парк, ничего особенного.",
    ["暴风回旋？这么可笑的名字，完全没听说过！"] = "Штормовой вихрь? Такое смешное имя, я никогда о нем не слышала!",
    ["更何况，你的广播体操也让工人们得到了锻炼，健康是最珍贵的东西。"] = "Кроме того, ваша радиогимнастика также помогла работникам тренироваться. Здоровье – это самое дорогое.",
    ["曾经的……夜之国。"] = "Бывшее... Королевство Ночи.",
    ["最后一波！撑住这条防线——挺过这波就结束了！"] = "Последняя волна! Держите оборону — выстоим сейчас, и всё закончится!",
    ["最终审判——别让任何人，独自走到尽头。"] = false,
    ["最近在这里经历了不少事情，虽然大多是在历史迷雾里……"] = "За последнее время я испытал здесь немало вещей, хотя большинство из них происходило в Тумане Истории...",
    ["最近我的记性是不是更差了。"] = "Ухудшилась ли моя память в последнее время?",
