    ["欢迎下次光临！"] = "Добро пожаловать в следующий раз!",
    ["欢迎你常来面包店。"] = "Добро пожаловать в пекарню часто.",
    ["欢迎品尝诅咒的味道！"] = "Добро пожаловать, чтобы ощутить вкус проклятия!",
    ["欢迎来到五月庄园，“尊贵”的客人。"] = "Добро пожаловать в Мэй Мэнор, «выдающийся» гость.",
    ["欢迎来到债务清偿现场。在这里，衣食住行不是权利，而是需要偿付的负债。"] = "Добро пожаловать на сцену урегулирования задолженности. Здесь еда, одежда, жилье и транспорт — это не права, а обязательства, за которые нужно платить.",
    ["欢迎来到斩杀线。底层的人每天都在线上挣扎，往前一步活一天；往后一步就掉下去。"] = "Добро пожаловать на линию казни. Люди внизу борются на кону каждый день; один шаг вперед, и они живут одним днем; один шаг назад, и они падают.",
    ["欢迎来到罗塞尔大帝的奇妙童话世界！（临时）"] = "Добро пожаловать в чудесный сказочный мир императора Розеллы! (Временный)",
