    ["白莉夫人被自称侠盗黑皇帝的人带走了，或许正面临危险，我得想想办法。"] = "Леди Берил похитил кто-то, назвавший себя Призрачным вором, Черным Императором. Она могла быть в опасности; Мне нужно придумать способ.",
    ["白银城前任首席科林，曾向“愚者”先生祈求，我主派我以“救赎”之名降临。"] = "Колин, бывший глава Серебряного города, однажды помолился Мистеруу, и мой Господь послал меня прийти во имя «спасения».",
    ["白银城的居民曾世代被隔绝在这里，遭受惨烈的诅咒，艰难探索两千多年。"] = "Жители Серебряного Города были изолированы здесь на протяжении нескольких поколений, страдая от жестокого проклятия и пытаясь исследовать мир на протяжении более двух тысяч лет.",
    ["百货商店里出售的木板应该能修复这张桌子。"] = "Деревянные доски, продаваемые в универмаге, помогут починить этот стол.",
    ["皇后的…任务……没能完成…（临时）"] = "Задание... Императрицы... не выполнено... (временно)",
    ["皮特不认识我，刚才在这里购买蜡烛……"] = "Пит меня не узнает, он только что покупал здесь свечи...",
    ["皮特到底要干什么？已经查到的这些线索……"] = "Что именно пытается сделать Пит? Эти подсказки мы уже нашли...",
    ["皮特要献祭自己，快阻止他进入仪式中心！"] = "Пит собирается принести себя в жертву, скорее остановите его, пока он не добрался до центра ритуала!",
    ["皮特，你欺骗我们？你的非凡力量呢？"] = "Пит, ты лжешь нам? А как насчет твоей необыкновенной силы?",
    ["皮特，你的饭量太大了，我经常以为自己养了两个表弟！"] = "Пит, ну и аппетит у тебя! Мне порой кажется, что я кормлю сразу двоих кузенов!",
    ["皮特，坚持住，你会没事的。"] = "Пит, держись, с тобой все будет в порядке.",
    ["皮特，靠这些并不能治好伊妮德！"] = "Пит, это не вылечит Инид!",
    ["皮特？"] = "Пит?",
    ["皮特？！就是他！"] = "Пит?! Это он!",
    ["目标的踪迹就在前面，大家小心行动。"] = "Следы цели прямо впереди. Будьте осторожны.",
    ["直接用之前拿到的《大冒险家》平装本，也是一个不错的选择？"] = "Использование экземпляра «Великого искателя приключений» в мягкой обложке, который я получил ранее, тоже хороший выбор, не так ли?",
    ["直接翻看会长的东西不太好……"] = "Не очень вежливо обсуждать дела президента напрямую...",
    ["相信我，就碰一下，你会获得足够多的报酬。"] = "Поверьте, просто прикоснитесь к нему, и вы получите достаточную награду.",
    ["看不见的东西……或许可以用【灵视】看一下"] = "Невидимые вещи... возможно, стоит взглянуть с помощью 【Духовного зрения】",
    ["看你还是一副疲劳的样子……想聊聊吗？"] = "Ты все еще выглядишь измотанным... хочешь поговорить об этом?",
    ["看你这副样子……想聊聊吗？"] = "Посмотри на себя... хочешь поговорить об этом?",
    ["看到科尔沁了。"] = "Я вижу Корчина.",
    ["看拳赛喝南威尔才带劲，{{PlayerName}}，你也来一杯？"] = "Смотреть бокс под пиво «Саутвелл» — самое то! {{PlayerName}}, плеснуть тебе кружечку?",
    ["看来你们并非对隐秘一无所知，接下来，就让我亲眼见识一番吧。"] = "Кажется, вы не совсем невежественны в отношении скрытого. Далее, позвольте мне увидеть самому.",
    ["看来它们不喜欢我。可惜，我也不喜欢现在的它们。"] = "Кажется, я им не нравлюсь. Жаль, они мне тоже не нравятся такими, какие они есть сейчас.",
    ["看来昨天的努力没有白费，事情总算往好的方向发展了。"] = "Кажется, вчерашние усилия не были напрасными; наконец-то дела идут в хорошем направлении.",
    ["看来是他急于汲取力量，导致笔记内蕴藏的超凡力量失控了！"] = "Похоже, его стремление поглотить силу привело к тому, что необычайная сила, содержащаяся в блокноте, вышла из-под контроля!",
    ["看来杜伦被变卖商铺这件事打动到了啊……其他人会不会也是呢。"] = "Кажется, Дюрен был тронут вопросом продажи магазина... Интересно, чувствуют ли остальные то же самое?",
    ["看来物品遗失并非偶然，而是一场预谋……继续调查，一定要追回失物。"] = "Похоже, пропажа вещей была не случайностью, а спланированным преступлением... Нужно продолжить расследование и обязательно вернуть украденное.",
    ["看来现在廷根的骑士很少，反而更好锁定了，说明只要找到骑士……就很可能是那个人。"] = "Похоже, сейчас в Тингене очень мало рыцарей, и сузить круг поиска проще: стоит лишь найти рыцаря... велика вероятность, что это окажется именно он.",
    ["看来福戈很在意孩子们的学业……沙曼好像也谅解了老莱纳的难处……"] = "Похоже, Фого очень заботится об образовании детей... Шаман, похоже, тоже простил трудности Олд Лейну...",
    ["看来要速战速决……现在就前往<P_Yellow>海岸线餐厅</>吧！"] = "Кажется, нам нужно действовать быстро... Давайте прямо сейчас отправимся в прибрежный ресторан <P_Yellow> </>!",
    ["看来这就是那头猎犬的主人了，果然，他也异变成为了怪物。"] = "Кажется, это хозяин той собаки. Как и ожидалось, он тоже мутировал в монстра.",
    ["看来这次的任务没那么简单……河岸好像有怨魂的气息残留，去前面搜寻一下吧。"] = "Кажется, эта миссия не так уж проста... на берегу реки витает аура Призрака. Давайте продолжим поиск.",
    ["看来这里就是那个邪神神使的藏身地了。"] = "Кажется, это убежище Посланника Злого Бога.",
    ["看来那两个人只是“英雄救美”中的劫匪演员，而这场戏的真实目的……"] = "Кажется, что эти двое — всего лишь актеры-разбойники в спектакле «герой спасает красоту», а настоящая цель этой пьесы…",
    ["看来那家伙破产了。这些金币，就当是这次调查的额外津贴吧。"] = "Похоже, этот парень обанкротился. Считайте эти золотые монеты дополнительным пособием для этого расследования.",
    ["看来，只要破解机关谜题，就能打破循环。"] = "Кажется, что пока загадка механизма решена, порочный круг можно разорвать.",
    ["看来，有必要跑一趟奥尔斯纳街。"] = "Кажется, необходимо съездить на улицу Ольсна.",
    ["看来，梦境也放大了他的表演欲。"] = "Кажется, этот сон еще больше усилил его желание выступать.",
    ["看来，需要把所有雏菊都转动到光亮之下。"] = "Похоже, нужно повернуть все маргаритки к свету.",
    ["看清楚了吗，要不要我动作放慢一点？"] = "Вы это ясно видели? Хочешь, чтобы я замедлил свои движения?",
    ["看看吧，看看吧，有钱能使鬼推磨，这些人，他们都会为了钱成为我的奴隶！"] = "Смотри, смотри! За деньги и черт спляшет! Все эти людишки за звонкую монету станут моими рабами!",
    ["看看我抓住了什么……一群小东西。"] = "Посмотрите, что я поймал... кучу мелочей.",
    ["看起来……更像是遗弃的废品。"] = "Выглядит... скорее как выброшенный хлам.",
    ["看起来危险程度不高。{{PlayerName}}，我们站在你身后，你来尝试解决它。"] = "Это не выглядит очень опасным. {{PlayerName}}, мы стоим за тобой, ты пытаешься решить эту проблему.",
    ["看起来它们还没开始改造文献室。"] = "Похоже, они еще не брались за перепланировку архива.",
    ["看起来很疼……"] = "Это выглядит больно...",
    ["看起来是报销单。他们活着的时候没见过这东西，不过……现在你可以替他们用了。"] = "Похоже на бланки возмещения. Они никогда не видели этих вещей, пока были живы, но... теперь вы можете использовать их от их имени.",
    ["看起来皮特吸收了过多的力量，已经失控成为非人的怪物"] = "Кажется, Пит впитал в себя слишком много силы и потерял контроль, превратившись в бесчеловечного монстра.",
    ["看起来，白莉夫人或许是对现实太过失望才会主动跟侠盗黑皇帝离开，但这也将她置于未知的危险之中。"] = "Похоже, леди Берил была слишком разочарована реальностью, чтобы добровольно уйти с Призрачным вором, Черным Императором, но это также подвергло ее неизвестной опасности.",
    ["看，从天而降的金雨就是这次的任务，接住这些金币。我们需要收拾现场。"] = "Смотри, на этот раз задача — золотой дождь, падающий с неба; поймай эти золотые монеты. Нам нужно очистить место происшествия.",
    ["真是一场灾难……"] = "Какая катастрофа...",
    ["真理啃食我，知识追逐我，我必须献上……痛苦的代价……"] = "Истина гложет меня, знание гонит меня; Я должен предложить... цену боли...",
    ["真的、真的……都是真的！"] = "Действительно, правда... все правда!",
    ["真难受，我一定要写首诗来记下这种感觉……"] = "Это так неудобно. Я должен написать стихотворение, чтобы передать это чувство...",
    ["知识……世界……都是囚笼！"] = "Знания... мир... все клетки!",
    ["知识……指引我……"] = "Знания... ведут меня...",
    ["知识……无穷的知识！接受知识的恩赐，接受伟大的眷顾！"] = "Знания... бесконечные знания! Прими дар знаний, прими великую благодать!",
    ["知识不能抵达的地方，胜利也不能。"] = "Там, где знание не может достичь, не может достичь и победа.",
    ["知识凝聚……守护激活……巨龙……出击！"] = "Знания сгущаются... Активируется защита... Гигантский дракон... Атака!",
    ["知识召唤你……绯红召唤你！"] = "Знания призывают тебя... Багрянец призывает тебя!",
    ["知识啊，赐予我守护的力量！"] = "Знание, даруй мне силу охранять!",
    ["知识皇冠不见了，但污染并没有消失……"] = "Корона Знаний исчезла, но порча не исчезла...",
    ["知识铸成的牢笼，正需要像你们这样的……玩物。"] = "Клетка, выкованная из знаний, нуждается в игрушках... как и ты.",
    ["知识，将为你设下牢笼。"] = false,
    ["石板泛出淡淡的微光，需要更强的光照来看清上面的文字！"] = "Каменная плита излучает слабое мерцание; Чтобы четко увидеть текст, необходим более сильный свет!",
    ["破碎不堪的意识会本能地寻找自己最熟悉的事物。"] = "Разрушенное сознание будет инстинктивно искать то, что ему наиболее знакомо.",
    ["确实没人——等等，这是？！"] = "Неужели никого нет — подождите, это?!",
    ["祂代表远古太阳神的暗面，被恶意、怨恨和堕落充满。"] = "Он представляет темную сторону Древнего Бога Солнца, наполненную злобой, негодованием и Искажением.",
    ["祖先的力量……"] = "Сила предков...",
    ["祝您好运，警官。"] = "Удачи, офицер.",
    ["神使大人……对不起……我太没用了……没能帮你挡住他们……"] = "Господин оракул... Простите... Я оказался бесполезен... Не сумел задержать их...",
    ["神圣的裁决粉碎一切！"] = "Божий суд разрушает все!",
